window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[155]={"id":"155","numero":155,"titre":"Infections cutanéo-muqueuses et des phanères","objectifs":[{"id":"155-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'une mycose superficielle","contenu":"<p>Une <span class=\"kw-def\">mycose superficielle</span> est une infection à <span class=\"kw-etio\">champignons</span> limitée à la <span class=\"kw-def\">couche cornée de l'épiderme</span>, aux <span class=\"kw-def\">phanères</span> (poils, cheveux, ongles) et/ou aux <span class=\"kw-clinique\">muqueuses</span>, sans <span class=\"kw-bio\">envahissement</span> profond.</p>\n      <p>On distingue <strong>deux grands groupes</strong> d'agents :</p>\n      <table >\n        <thead><tr><th>Groupe</th><th>Agents &amp; caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Champignons filamenteux</strong></td>\n            <td><span class=\"kw-etio\">Dermatophytes</span> (genres <span class=\"kw-etio\">Epidermophyton</span>, <span class=\"kw-etio\">Microsporum</span>, <span class=\"kw-etio\">Trichophyton</span>) : <span class=\"kw-bio\">toujours pathogènes</span>, kératinophiles, <span class=\"kw-bio\">ne sont jamais saprophytes</span> et <span class=\"kw-bio\">respectent les muqueuses</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Levures</strong></td>\n            <td><span class=\"kw-etio\">Candida albicans</span> : <span class=\"kw-bio\">saprophyte des muqueuses</span> digestives/génitales, <span class=\"kw-def\">pathogène opportuniste</span> sous facteurs favorisants.<br><span class=\"kw-etio\">Malassezia furfur</span> : levure <span class=\"kw-bio\">lipophile commensale</span> de la peau grasse (<span class=\"kw-etio\">pityriasis</span> versicolor).</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">💡 Discriminant : <span class=\"kw-etio\">Candida albicans</span> est <span class=\"kw-bio\">toujours pathogène en site cutané</span> mais un simple <span class=\"kw-bio\">saprophyte</span> en site muqueux digestif/génital → l'interprétation d'une culture dépend du site de prélèvement.</div>","frequence":0},{"id":"155-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes d'une infection candidosique et des mycoses (candidoses incluses) orale, génitale, unguéale, d'un pli","contenu":"<p>Sémiologie par localisation, avec le grand <strong>discriminant <span class=\"kw-etio\">Candida</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-etio\">Dermatophyte</span></strong> :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Candida</th><th>Dermatophytes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Localisation des plis</strong></td><td><span class=\"kw-clinique\">Grands plis</span> surtout, <span class=\"kw-clinique\">bilatéral et symétrique</span> ; pieds = <span class=\"kw-clinique\">1ᵉʳ espace</span></td><td><span class=\"kw-clinique\">Petits plis</span> surtout (pieds, <span class=\"kw-clinique\">3ᵉ-4ᵉ espace</span>) ; grand pli inguinal <span class=\"kw-clinique\">unilatéral</span></td></tr>\n          <tr><td><strong>Fond du pli</strong></td><td><span class=\"kw-clinique\">Érythémateux</span>, enduit blanchâtre, <span class=\"kw-clinique\">fissure</span> au fond, suintant et prurigineux</td><td>Fond <span class=\"kw-clinique\">sec non érythémateux</span></td></tr>\n          <tr><td><strong>Bord</strong></td><td>Bord émietté, fine collerette desquamative/pustuleuse</td><td>Bordure <span class=\"kw-clinique\">arrondie/polycyclique érythémato-squameuse</span> (<span class=\"kw-clinique\">extension centrifuge, guérison centrale</span>)</td></tr>\n          <tr><td><strong>Ongle (onyxis)</strong></td><td><span class=\"kw-clinique\">Périonyxis</span> dès le début, <span class=\"kw-clinique\">mains ++</span></td><td><span class=\"kw-bio\">Pas de périonyxis</span>, <span class=\"kw-clinique\">orteils ++</span>, début distal</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Orale :</strong> <span class=\"kw-clinique\">muguet</span> (<span class=\"kw-clinique\">érythème</span> + enduit blanchâtre détachable au raclage), <span class=\"kw-clinique\">perlèche</span> (intertrigo de la commissure labiale), <span class=\"kw-clinique\">glossite</span> dépapillée en avant du V lingual, <span class=\"kw-clinique\">xérostomie</span> et <span class=\"kw-clinique\">dysgueusie</span>.</li>\n        <li><strong>Génitale (femme) :</strong> <span class=\"kw-clinique\">vulvovaginite</span> — <span class=\"kw-clinique\">prurit +++</span>, <span class=\"kw-clinique\">leucorrhées blanc-jaunâtre « lait caillé »</span> grumeleuses, <span class=\"kw-clinique\">érythème</span>/<span class=\"kw-clinique\">œdème</span> vulvaire ± dyspareunie.</li>\n        <li><strong>Génitale (homme) :</strong> <span class=\"kw-clinique\">balanite / balano-posthite</span> (<span class=\"kw-clinique\">érythème</span> du gland, picotements après rapport), souvent paucisymptomatique.</li>\n        <li><strong>Unguéale :</strong> <span class=\"kw-etio\">Candida</span> = <span class=\"kw-clinique\">périonyxis</span> douloureux puis <span class=\"kw-clinique\">onyxis</span> proximal marron-verdâtre (mains) ; <span class=\"kw-etio\">dermatophyte</span> = <span class=\"kw-clinique\">leuconychie</span> → <span class=\"kw-clinique\">hyperkératose sous-unguéale</span> → <span class=\"kw-clinique\">onycholyse</span> distale (orteils).</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — Endocardite infectieuse</em></p>","frequence":1},{"id":"155-3","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les facteurs favorisants des infections cutanéo muqueuses à candida et mycoses","contenu":"<p><span class=\"kw-etio\">Candida albicans</span> passe de l'état <span class=\"kw-bio\">saprophyte</span> à l'état <span class=\"kw-bio\">parasitaire</span> uniquement sous l'influence de facteurs favorisants (<span class=\"kw-def\">déséquilibre de la flore muqueuse</span> +++).</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Facteurs favorisants</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Candida</span> — locaux</strong></td>\n            <td><span class=\"kw-clinique\">Chaleur</span> ; <span class=\"kw-clinique\">humidité / macération</span> ; <span class=\"kw-chiffre\">pH acide</span> ; milieu <span class=\"kw-clinique\">riche en sucre</span> ; <span class=\"kw-clinique\">obésité</span> ; <span class=\"kw-clinique\">prothèses dentaires</span> ; <span class=\"kw-clinique\">xérostomie</span> ; mucite post-radique ; contact répété avec l'eau (<span class=\"kw-clinique\">plongeur</span>) ou le sucre (<span class=\"kw-clinique\">pâtissier</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Candida</span> — généraux</strong></td>\n            <td><span class=\"kw-clinique\">Immunodépression</span> (<span class=\"kw-etio\">VIH</span>, <span class=\"kw-ttt\">corticoïdes</span>, cancer, dénutrition) ; <span class=\"kw-clinique\">diabète</span> ; <span class=\"kw-clinique\">âges extrêmes</span> ; <span class=\"kw-clinique\">grossesse</span> ; <span class=\"kw-ttt\">antibiothérapie systémique</span> ; <span class=\"kw-ttt\">œstroprogestatifs</span></td>\n          </tr>\n          <tr>\n            <td><strong>Dermatophytes</strong></td>\n            <td><span class=\"kw-clinique\">Milieu sportif</span> (douches collectives, tatamis) ; <span class=\"kw-clinique\">macération</span> ; <span class=\"kw-bio\">altération épidermique</span> (microtraumatisme) ; contact animal (chien/chat) ; <span class=\"kw-ttt\">corticoïdes locaux</span> (favorisent les <span class=\"kw-bio\">teignes</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Malassezia</span></strong> (<span class=\"kw-etio\">pityriasis</span> versicolor)</td>\n            <td><span class=\"kw-clinique\">Peau grasse</span> ; <span class=\"kw-clinique\">sudation</span> ; <span class=\"kw-clinique\">chaleur</span> ; <span class=\"kw-clinique\">humidité</span> ; l'<span class=\"kw-clinique\">été</span> / voyages tropicaux</td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"155-4","rang":"A","rubrique":"Contenu multimédia","titre":"Photographies d'un exemple typique de ces mycoses","contenu":"<p>Reconnaître les présentations typiques sur photographie est <strong>très tombable</strong> à l'EDN.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/155/teigne-tondante-microsporique.png\" alt=\"Teigne tondante à Microsporum canis : grande plaque alopécique unique du cuir chevelu, squameuse, à cheveux cassés courts\" loading=\"lazy\">\n        <figcaption><span class=\"kw-etio\">Teigne</span> tondante <span class=\"kw-etio\">microsporique</span> (<span class=\"kw-etio\">M. canis</span>) : <span class=\"kw-clinique\">grande plaque alopécique unique</span>, arrondie, squameuse, cheveux cassés courts. Source : fiche source EDN item 155.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/155/dermatophytie-ungueale-trubrum.png\" alt=\"Onychomycose dermatophytique à Trichophyton rubrum d'un doigt avec périonyxis\" loading=\"lazy\">\n        <figcaption>Dermatophytie unguéale à <span class=\"kw-etio\">T. rubrum</span> : <span class=\"kw-clinique\">leuconychie</span> et <span class=\"kw-clinique\">onycholyse</span> distale. Source : fiche source EDN item 155.</figcaption>\n      </figure>\n      <ul>\n        <li><strong>Intertrigo candidosique :</strong> fond du pli <span class=\"kw-clinique\">érythémateux suintant</span>, enduit blanchâtre, <span class=\"kw-clinique\">fissure</span>, <span class=\"kw-clinique\">bilatéral et symétrique</span>.</li>\n        <li><strong>Dermatophytie de la peau glabre («&nbsp;herpès circiné&nbsp;») :</strong> <span class=\"kw-clinique\">plaque arrondie</span> à <span class=\"kw-clinique\">bordure vésiculo-squameuse</span>, <span class=\"kw-clinique\">guérison centrale</span>.</li>\n        <li><strong><span class=\"kw-etio\">Pityriasis</span> versicolor :</strong> <span class=\"kw-clinique\">macules chamois</span> du tronc, <span class=\"kw-clinique\">achromiques après exposition solaire</span>, non prurigineuses.</li>\n        <li><strong>Muguet :</strong> <span class=\"kw-clinique\">enduit blanchâtre</span> détachable sur muqueuse buccale érythémateuse.</li>\n      </ul>","frequence":6},{"id":"155-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications du prélèvement mycologique de la peau et des phanères","contenu":"<p>Le <span class=\"kw-bio\">prélèvement mycologique</span> doit être réalisé <strong>avant tout traitement <span class=\"kw-ttt\">antifongique</span></strong> (ou après fenêtre thérapeutique de <span class=\"kw-chiffre\">≥ 2 semaines</span>).</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Indication du prélèvement</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Dermatophytes</strong></td><td><span class=\"kw-bio\">Indispensable</span>, <span class=\"kw-ci\">sauf intertrigo interorteils</span> (diagnostic clinique) ; surtout pour les <span class=\"kw-clinique\">atteintes phanériennes</span> (ongles, cuir chevelu) avant tout <span class=\"kw-ttt\">antifongique</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Candida</span></strong></td><td><span class=\"kw-bio\">Pas systématique</span> si clinique évidente ; réalisé si <span class=\"kw-clinique\">atypie</span>/doute, lésions <span class=\"kw-clinique\">chroniques ou récidivantes</span>, ou <span class=\"kw-clinique\">résistance</span> au traitement bien conduit</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Prélèvements :</strong> <span class=\"kw-bio\">squames</span>, <span class=\"kw-bio\">cheveux</span>, fragment d'<span class=\"kw-bio\">ongle</span> ; <span class=\"kw-ci\">pas d'écouvillonnage</span> pour les dermatophytes (écouvillon possible pour <span class=\"kw-etio\">Candida</span> muqueux/cutané).</li>\n        <li><strong>Examen direct :</strong> pose le diagnostic — <span class=\"kw-bio\">filaments septés</span> (dermatophytes), <span class=\"kw-bio\">levures bourgeonnantes ± pseudo-filaments</span> (<span class=\"kw-etio\">Candida</span> = élément de pathogénicité).</li>\n        <li><strong>Culture sur milieu de Sabouraud :</strong> <span class=\"kw-chiffre\">3-4 semaines</span> (dermatophytes) <span class=\"kw-bio\">vs</span> <span class=\"kw-chiffre\">24-48 h</span> (<span class=\"kw-etio\">Candida</span>) ; précise le genre et l'espèce.</li>\n        <li><strong>Lampe de Wood :</strong> <span class=\"kw-bio\">fluorescence jaune-vert</span> des poils (dermatophytose microsporique) ; <span class=\"kw-bio\">rouge corail</span> = érythrasma (DD).</li>\n      </ul>","frequence":2},{"id":"155-6","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement des mycoses (candidoses incluses)","contenu":"<p>Principes communs : <span class=\"kw-ttt\">suppression des facteurs favorisants</span> (macération), <strong>traitement simultané de tous les foyers</strong>, choix de la molécule selon localisation/étendue/<span class=\"kw-def\">terrain</span>.</p>\n      <table >\n        <thead><tr><th>Voie</th><th>Molécules &amp; indications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Locale</strong> (1ʳᵉ intention)</td>\n            <td><span class=\"kw-ttt\">Imidazolés</span> (1ʳᵉ intention) ; <span class=\"kw-ttt\">ciclopiroxolamine</span> ; <span class=\"kw-ttt\">terbinafine</span> locale ; <span class=\"kw-ttt\">amphotéricine B</span> (suspension buvable, foyer muqueux). Durée <span class=\"kw-chiffre\">2-4 semaines</span> (<span class=\"kw-etio\">Candida</span>) ou <span class=\"kw-chiffre\">2-3 semaines</span> azolé / <span class=\"kw-chiffre\">1 semaine</span> terbinafine (dermatophytose des plis)</td>\n          </tr>\n          <tr>\n            <td><strong>Systémique</strong></td>\n            <td>Si atteinte <span class=\"kw-clinique\">étendue</span>, <span class=\"kw-clinique\">phanérienne</span> (ongle, cuir chevelu), <span class=\"kw-clinique\">palmoplantaire</span> ou contexte d'<span class=\"kw-clinique\">immunodépression</span> : <span class=\"kw-ttt\">fluconazole</span> (<span class=\"kw-etio\">Candida</span>) ; <span class=\"kw-ttt\">terbinafine</span>, <span class=\"kw-ttt\">griséofulvine</span> (à associer au local), <span class=\"kw-ttt\">itraconazole</span> (dermatophytes)</td>\n          </tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Teigne</span> :</strong> traitement <span class=\"kw-ttt\">local + systémique impératif</span> pendant <span class=\"kw-chiffre\">≥ 6 semaines</span> ; <span class=\"kw-ci\">pas d'éviction scolaire si traité</span> ; <span class=\"kw-ci\">pas une maladie à déclaration obligatoire</span>.</li>\n        <li><strong>Onychomycose :</strong> traitement long (guérison à la repousse : <span class=\"kw-chiffre\">4-6 mois</span> mains, <span class=\"kw-chiffre\">9-12 mois</span> orteils).</li>\n        <li><strong><span class=\"kw-etio\">Pityriasis</span> versicolor :</strong> <span class=\"kw-ttt\">gel kétoconazole</span> à répéter à<span class=\"kw-chiffre\"> 48 h</span>.</li>\n        <li><strong>Candidose buccale :</strong> <span class=\"kw-ttt\">antifongique</span> local en contact prolongé (amphotéricine B, nystatine, miconazole gel) ; <span class=\"kw-ttt\">fluconazole</span> PO si récidive/immunodépression.</li>\n      </ul>\n      <div class=\"callout callout-danger\">⚠️ <span class=\"kw-ci\">Aucun antifongique per os n'est autorisé chez la femme enceinte.</span> Chez l'enfant, seule la <span class=\"kw-ttt\">griséofulvine</span> a l'AMM.</div>","frequence":4},{"id":"155-7","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'un panaris","contenu":"<p>Un <span class=\"kw-def\">panaris</span> est une <span class=\"kw-def\">infection aiguë du repli unguéal</span> (<span class=\"kw-clinique\">péri-unguéale</span>), le plus souvent à <span class=\"kw-etio\">Staphylococcus aureus</span>.</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Lésion</span> élémentaire :</strong> <span class=\"kw-clinique\">repli unguéal</span> <span class=\"kw-clinique\">érythémateux</span>, <span class=\"kw-clinique\">œdémateux</span> et <span class=\"kw-clinique\">douloureux</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Évolution</span> :</strong> <span class=\"kw-def\">stade</span> <span class=\"kw-clinique\">phlegmasique</span> initial puis possible <span class=\"kw-clinique\">collection purulente</span>.</li>\n        <li><strong><span class=\"kw-def\">Diagnostic différentiel</span> :</strong> <span class=\"kw-clinique\">panaris herpétique</span> (vésicules groupées, profession de santé) — à ne pas inciser.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Rechercher un <span class=\"kw-clinique\">corps étranger</span> ou une <span class=\"kw-clinique\">porte d'entrée</span> (piqûre, manucure) ; vérifier le statut <span class=\"kw-ttt\">antitétanique</span>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Dermatologie.</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 349 — Infection des parties molles</em></p>","frequence":0},{"id":"155-8","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'un abcès","contenu":"<p>Un <span class=\"kw-def\">abcès</span> est une <span class=\"kw-def\">collection de pus</span> — il représente un <span class=\"kw-def\">mode de résolution physiologique imparfait</span> d'une infection locale (germe principal : <span class=\"kw-etio\">S. aureus</span>).</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Lésion</span> :</strong> <span class=\"kw-clinique\">plaque ou nodule érythémateux</span> <span class=\"kw-clinique\">inflammatoire</span> <span class=\"kw-clinique\">très douloureux</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Évolution</span> :</strong> vers la <span class=\"kw-clinique\">collection</span> en <span class=\"kw-chiffre\">quelques jours</span> — consistance <span class=\"kw-clinique\">molle</span>, <span class=\"kw-clinique\">fluctuation</span> à la palpation.</li>\n        <li><strong>Signes généraux :</strong> <span class=\"kw-clinique\">fièvre souvent absente</span>, <span class=\"kw-clinique\">état général conservé</span> ; ± <span class=\"kw-clinique\">lymphangite</span> et/ou <span class=\"kw-clinique\">adénopathies satellites</span>.</li>\n        <li><strong>Germes :</strong> <span class=\"kw-etio\">S. aureus</span> ++ ; recherche de <span class=\"kw-bio\">leucocidine de Panton-Valentine</span> si <span class=\"kw-clinique\">récidive</span>/épidémies familiales.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Dermatologie.</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 349 — Infection des parties molles</em></p>","frequence":0},{"id":"155-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement d'un abcès","contenu":"<ul>\n        <li><strong>Geste clé :</strong> <span class=\"kw-ttt\">incision + drainage</span> de l'<span class=\"kw-clinique\">abcès</span> (<span class=\"kw-clinique\">évacuation du pus</span>).</li>\n        <li><strong><span class=\"kw-ttt\">Antibiothérapie</span> :</strong> <span class=\"kw-ttt\">ATB orale</span> <span class=\"kw-chiffre\">5 jours</span> si indiquée — <span class=\"kw-ttt\">clindamycine</span> ou <span class=\"kw-ttt\">pristinamycine</span> ou <span class=\"kw-ttt\">oxacilline/cloxacilline</span>.</li>\n        <li><strong>Prélèvement bactériologique systématique</strong> (identification, <span class=\"kw-bio\">antibiogramme</span>) :\n          <ul>\n            <li><span class=\"kw-clinique\">Abcès</span> primaire/récidivant, petites épidémies familiales → recherche de <span class=\"kw-bio\">leucocidine de Panton-Valentine</span> (<span class=\"kw-etio\">S. aureus</span>).</li>\n            <li><span class=\"kw-clinique\">Abcès</span> secondaire (inoculation, toxicomanie) → <span class=\"kw-etio\">S. aureus</span> ++.</li>\n          </ul>\n        </li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Émergence du <span class=\"kw-etio\">SARM communautaire (SARM-CO)</span>, responsable d'infections suppuratives dont de nombreux <span class=\"kw-clinique\">abcès</span> parfois nécrotiques.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Dermatologie.</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 349 — Infection des parties molles</em></p>","frequence":0},{"id":"155-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement d'un panaris","contenu":"<ul>\n        <li><strong><span class=\"kw-def\">Stade</span> <span class=\"kw-clinique\">phlegmasique</span> (débutant) :</strong> <span class=\"kw-ttt\">antiseptiques locaux</span>.</li>\n        <li><strong><span class=\"kw-ttt\">Antibiothérapie</span> :</strong> <span class=\"kw-ttt\">ATB antistaphylococcique per os</span> en cas de <span class=\"kw-clinique\">résistance</span> et/ou de <span class=\"kw-clinique\">complication</span>.</li>\n        <li><strong><span class=\"kw-def\">Stade</span> <span class=\"kw-clinique\">collecté</span> :</strong> <span class=\"kw-ttt\">incision + drainage</span> en cas de <span class=\"kw-clinique\">collection purulente</span>.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Dermatologie.</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 349 — Infection des parties molles</em></p>","frequence":0},{"id":"155-11","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'une dermohypodermite bactérienne non nécrosante et nécrosante","contenu":"<p>Les <span class=\"kw-def\">dermohypodermites bactériennes (DHB)</span> sont des infections du <span class=\"kw-def\">derme et de l'hypoderme</span>, dues à des <span class=\"kw-etio\">cocci Gram positif</span> (<span class=\"kw-etio\">Streptococcus pyogenes</span>, <span class=\"kw-etio\">Staphylococcus aureus</span>).</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>DHB non nécrosante</strong></td>\n            <td>= <span class=\"kw-def\">érysipèle</span> (et infections anciennement « cellulites ») ; extension <span class=\"kw-clinique\">limitée au derme et à l'hypoderme</span>, <span class=\"kw-bio\">pas de nécrose</span></td>\n          </tr>\n          <tr>\n            <td><strong>DHB nécrosante</strong></td>\n            <td>Atteinte s'étendant jusqu'aux <span class=\"kw-clinique\">fascias</span> (= <span class=\"kw-def\">fasciite nécrosante</span> à l'exploration chirurgicale) ; <span class=\"kw-alerte\">atteinte musculaire possible tardive</span> ; <span class=\"kw-clinique\">exploration et PEC chirurgicale</span> toujours nécessaires</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">💡 La <span class=\"kw-etio\">myonécrose</span> (myosite clostridiale = « <span class=\"kw-alerte\"><span class=\"kw-clinique\">gangrène</span> gazeuse</span> » à <span class=\"kw-etio\">Clostridium perfringens</span>) atteint primitivement le muscle ; devenue rare.</div>","frequence":1},{"id":"155-12","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'épidémiologie et les facteurs de risque des dermohypodermites bactériennes non nécrosantes et nécrosantes chez l'adulte et l'enfant","contenu":"<p><strong><span class=\"kw-def\">Épidémiologie</span> :</strong> <span class=\"kw-clinique\">érysipèle</span> = maladie <span class=\"kw-clinique\">fréquente</span>, adulte <span class=\"kw-chiffre\">&gt; 40 ans</span> (âge moyen <span class=\"kw-chiffre\">60 ans</span>) ; forme nécrosante <span class=\"kw-chiffre\">100× plus rare</span>. Chez l'<span class=\"kw-clinique\">enfant</span>, le principal facteur favorisant des DHB non nécrosantes est la <span class=\"kw-etio\">varicelle</span>.</p>\n      <table >\n        <thead><tr><th>FR d'érysipèle (DHB non nécrosante)</th><th>FR de <span class=\"kw-alerte\">fasciite nécrosante</span> / DHB nécrosante</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <span class=\"kw-clinique\">ATCD personnel d'érysipèle</span><br>\n              <span class=\"kw-clinique\">Obésité</span> (IMC &gt; 30)<br>\n              <span class=\"kw-clinique\">Œdème chronique / lymphœdème</span><br>\n              <span class=\"kw-clinique\">Porte d'entrée cutanée</span> (intertrigo, ulcère)<br>\n              <span class=\"kw-clinique\">Varicelle</span> (enfant)\n            </td>\n            <td>\n              <span class=\"kw-clinique\">Âge &gt; 60 ans</span><br>\n              <span class=\"kw-clinique\">Obésité</span> (IMC &gt; 30)<br>\n              <span class=\"kw-clinique\">Diabète</span>, <span class=\"kw-clinique\">immunodépression</span>, <span class=\"kw-clinique\">toxicomanie IV</span>, <span class=\"kw-clinique\">malnutrition</span><br>\n              <span class=\"kw-clinique\">Insuffisance veineuse</span>, <span class=\"kw-clinique\">AOMI</span><br>\n              <span class=\"kw-ci\">AINS</span><br>\n              <span class=\"kw-clinique\">Varicelle</span> (enfant)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ Piège classique : les <span class=\"kw-ci\">AINS</span> sont un FR (et un facteur aggravant) des formes <strong>nécrosantes</strong> — à ne pas prescrire devant une grosse jambe rouge.</div>","frequence":3},{"id":"155-13","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les orientations diagnostiques d'une grosse jambe rouge aiguë","contenu":"<p>Devant une <span class=\"kw-clinique\">grosse jambe rouge aiguë</span>, l'<span class=\"kw-def\">érysipèle</span> est le <strong>1ᵉʳ diagnostic à évoquer</strong> (surtout si fébrile et unilatéral). Démarche d'orientation :</p>\n      <table >\n        <thead><tr><th>Orientation</th><th>Arguments</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Érysipèle</span></strong> (DHB non nécrosante)</td><td><span class=\"kw-clinique\">Fièvre brutale</span>, <span class=\"kw-clinique\">placard inflammatoire unilatéral</span>, douloureux, porte d'entrée</td></tr>\n          <tr><td><strong>DHB nécrosante</strong> ⚠️</td><td><span class=\"kw-alerte\">Douleur disproportionnée</span>, <span class=\"kw-alerte\">nécrose</span>, <span class=\"kw-alerte\">sepsis</span>, extension malgré ATB → <span class=\"kw-alerte\">urgence</span> chirurgicale</td></tr>\n          <tr><td><strong>Thrombose veineuse profonde</strong></td><td><span class=\"kw-clinique\">Jambe rouge/chaude</span>, mais <span class=\"kw-clinique\">douleur du mollet</span>, contexte thrombogène ; <span class=\"kw-bio\">écho-doppler</span></td></tr>\n          <tr><td><strong>Causes non infectieuses</strong></td><td><span class=\"kw-clinique\">Eczéma aigu</span>, <span class=\"kw-clinique\">poussée d'insuffisance veineuse / dermite de stase</span> (souvent <span class=\"kw-clinique\">bilatéral</span>, <span class=\"kw-clinique\">peu fébrile</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">💡 Le caractère <span class=\"kw-clinique\">unilatéral + fièvre</span> oriente vers l'<span class=\"kw-clinique\">érysipèle</span> ; un tableau <span class=\"kw-clinique\">bilatéral non fébrile</span> oriente vers une cause veineuse/eczémateuse.</div>","frequence":0},{"id":"155-14","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes sémiologiques évocateurs de dermohypodermite bactérienne chez l'adulte et chez l'enfant","contenu":"<p>Tableau typique d'<span class=\"kw-def\">érysipèle</span> (DHB non nécrosante) :</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Fièvre</span> :</strong> <span class=\"kw-clinique\">brutale</span>, élevée <span class=\"kw-chiffre\">39-40 °C</span> ± <span class=\"kw-clinique\">frissons</span>, <span class=\"kw-clinique\">précédant souvent de quelques heures les lésions</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Placard</span> <span class=\"kw-etio\">inflammatoire</span> :</strong> <span class=\"kw-clinique\">rouge, chaud, œdémateux, douloureux</span>, <span class=\"kw-clinique\">unilatéral</span>, début brutal, extension rapide (<span class=\"kw-clinique\">marquer les contours au feutre</span>).</li>\n        <li><strong>Signes associés :</strong> <span class=\"kw-clinique\">adénopathie satellite</span>, <span class=\"kw-clinique\">lymphangite</span> (inconstantes mais fréquentes).</li>\n        <li><strong>Au visage :</strong> <span class=\"kw-clinique\">bourrelet périphérique</span> (limite nette surélevée), croûtes, pustules.</li>\n        <li><strong>Signes non graves :</strong> <span class=\"kw-clinique\">décollement bulleux superficiel</span> (<span class=\"kw-clinique\">œdème</span> dermique), <span class=\"kw-clinique\">purpura localisé</span> sur le <span class=\"kw-clinique\">placard</span> — ne sont <span class=\"kw-bio\">pas</span> des <span class=\"kw-alerte\"><span class=\"kw-def\">critères de</span> gravité</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Chez l'<span class=\"kw-clinique\">enfant</span>, la DHB non nécrosante survient volontiers au décours d'une <span class=\"kw-etio\">varicelle</span>.</div>\n      <div class=\"callout callout-danger\">⚠️ <span class=\"kw-alerte\">Drapeau rouge</span> : absence de signes de <span class=\"kw-alerte\">sepsis</span> et de <span class=\"kw-clinique\">nécrose</span> est attendue dans l'<span class=\"kw-clinique\">érysipèle</span> — sinon, suspecter une <span class=\"kw-alerte\">forme nécrosante</span>.</div>","frequence":2},{"id":"155-15","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les localisations les plus fréquentes de dermohypodermite bactérienne non nécrosante et nécrosantes","contenu":"<table >\n        <thead><tr><th>Forme</th><th>Localisations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Non nécrosante (<span class=\"kw-clinique\">érysipèle</span>)</strong></td>\n            <td><strong>Membres inférieurs :</strong> <span class=\"kw-clinique\">90 %</span><br><strong>Visage :</strong> <span class=\"kw-clinique\">5-10 %</span> (<span class=\"kw-clinique\">staphylococcie maligne</span> si <span class=\"kw-etio\">S. aureus</span>)<br><strong><span class=\"kw-clinique\">Membre supérieur</span> :</strong> si <span class=\"kw-clinique\">ATCD de curage ganglionnaire</span><br><strong><span class=\"kw-clinique\">Thorax</span> :</strong> si <span class=\"kw-clinique\">ATCD de thoracotomie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Nécrosante</strong></td>\n            <td><span class=\"kw-clinique\">Membres inférieurs</span> le plus souvent<br><span class=\"kw-clinique\">Cervico-faciale</span> (risque de <span class=\"kw-alerte\">médiastinite</span>)<br><span class=\"kw-clinique\">Thoraco-abdominale</span><br><span class=\"kw-clinique\">Périnéale</span> = <span class=\"kw-clinique\">gangrène de Fournier</span></td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"155-16","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes de gravité d'une dermohypodermite","contenu":"<p>Les <span class=\"kw-alerte\">signes de gravité</span> font basculer vers la <span class=\"kw-alerte\">DHB nécrosante / fasciite nécrosante</span> — <strong><span class=\"kw-alerte\">urgence</span> médico-chirurgicale</strong> :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Douleur intense</span> dépassant les zones inflammatoires, <span class=\"kw-alerte\">non calmée par les antalgiques de palier 1-2</span>.</li>\n        <li><span class=\"kw-alerte\">Extension rapide des lésions malgré une antibiothérapie bien conduite</span>.</li>\n        <li><span class=\"kw-alerte\">Induration</span> des tissus au-delà de l'<span class=\"kw-clinique\">érythème</span> visible.</li>\n        <li><span class=\"kw-alerte\">Crépitation neigeuse</span> (germes anaérobies).</li>\n        <li><span class=\"kw-alerte\">Nécrose cutanée</span> : zones livedoïdes, taches cyaniques, plaques noirâtres.</li>\n        <li><span class=\"kw-alerte\">Bulles séro-hématiques / hémorragiques</span>, <span class=\"kw-alerte\">écoulement fétide</span>.</li>\n        <li><span class=\"kw-alerte\">Hypoesthésie tardive</span> (anesthésie douloureuse) ; <span class=\"kw-alerte\">sepsis</span> : <span class=\"kw-bio\">qSOFA ≥ 2</span> (FR <span class=\"kw-chiffre\">≥ 22/min</span>, PAS <span class=\"kw-chiffre\">≤ 100 mmHg</span>, Glasgow &lt; 15).</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/155/dermohypodermite-necrosante-sga.png\" alt=\"Dermohypodermite nécrosante à streptocoque du groupe A : placard livedoïde nécrotique du membre\" loading=\"lazy\">\n        <figcaption>Dermohypodermite nécrosante à <span class=\"kw-etio\">streptocoque du groupe A</span> : <span class=\"kw-clinique\">nécrose</span> cutanée et zones livedoïdes. Source : fiche source EDN item 155.</figcaption>\n      </figure>\n      <div class=\"callout callout-warn\">⚠️ <span class=\"kw-clinique\">Phlyctène</span>, <span class=\"kw-clinique\">décollement bulleux</span> et <span class=\"kw-clinique\">purpura</span> localisé <strong>ne sont PAS</strong> des <span class=\"kw-alerte\">signes de gravité</span> (présents dans l'<span class=\"kw-clinique\">érysipèle</span> non compliqué).</div>","frequence":0},{"id":"155-17","rang":"A","rubrique":"Contenu multimédia","titre":"Dermohypodermite bactérienne non nécrosante (photographies d'un érysipéle adulte, d'une dermohypodermite non nécrosante enfant)","contenu":"<p>Sémiologie photographique d'une <span class=\"kw-def\">DHB non nécrosante</span> :</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Érysipèle</span> de l'adulte :</strong> <span class=\"kw-clinique\">placard inflammatoire unilatéral</span> du <span class=\"kw-clinique\">membre inférieur</span>, <span class=\"kw-clinique\">rouge</span>, <span class=\"kw-clinique\">chaud</span>, <span class=\"kw-clinique\">œdémateux</span>, <span class=\"kw-clinique\">douloureux</span>, à <span class=\"kw-clinique\">limite nette</span> ; ± <span class=\"kw-clinique\">bourrelet périphérique</span> (visage), <span class=\"kw-clinique\">décollement bulleux</span> superficiel, <span class=\"kw-clinique\">purpura localisé</span>.</li>\n        <li><strong>DHB non nécrosante de l'enfant :</strong> <span class=\"kw-clinique\">placard érythémateux</span> souvent au décours d'une <span class=\"kw-etio\">varicelle</span> ; rechercher la <span class=\"kw-clinique\">porte d'entrée</span> et l'<span class=\"kw-clinique\">adénopathie satellite</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ <strong>Image à venir.</strong> Aucune photographie d'<span class=\"kw-clinique\">érysipèle non nécrosante</span> dans les fiches sources. Kevin déposera <code>erysipele-adulte.png</code> + <code>dhbnn-enfant.png</code> dans <code>assets/images/155/</code>, puis on câblera le <code>&lt;figure&gt;</code>.</div>\n      <!-- TODO Kevin : déposer erysipele-adulte.png + dhbnn-enfant.png dans assets/images/155/ puis ajouter le <figure class=\"obj-figure\"> correspondant -->","frequence":1},{"id":"155-18","rang":"A","rubrique":"Examens complémentaires","titre":"Dermohypodermite bactérienne non nécrosante : connaître les examens à réaliser (et à ne pas réaliser)","contenu":"<div class=\"callout callout-danger\">⚠️ Dans la forme <strong>typique non compliquée</strong> d'<span class=\"kw-clinique\">érysipèle</span> : <span class=\"kw-ci\">aucun examen complémentaire n'est nécessaire</span>.</div>\n      <ul>\n        <li><strong>Biologie (si réalisée) :</strong> <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span> → <span class=\"kw-bio\">syndrome inflammatoire</span> avec <span class=\"kw-bio\">hyperleucocytose à PNN</span>.</li>\n        <li><strong>Prélèvements microbiologiques</strong> (porte d'entrée + <span class=\"kw-bio\">hémocultures</span>) uniquement si :\n          <ul>\n            <li><span class=\"kw-clinique\">Morsure</span> animale/humaine, contexte <span class=\"kw-clinique\">post-traumatique</span> ;</li>\n            <li><span class=\"kw-clinique\">Voyage</span>, survenue en <span class=\"kw-clinique\">milieu aquatique</span> ;</li>\n            <li>Patient <span class=\"kw-clinique\">immunodéprimé</span>, infection <span class=\"kw-clinique\">nosocomiale</span> ;</li>\n            <li><span class=\"kw-alerte\">Signes de gravité</span> locaux ou généraux.</li>\n          </ul>\n        </li>\n      </ul>\n      <div class=\"callout callout-info\">💡 <span class=\"kw-bio\">Hémocultures</span> positives dans <span class=\"kw-chiffre\">&lt; 5 %</span> des érysipèles (prolifération <span class=\"kw-etio\">bactérienne</span> paradoxalement faible).</div>","frequence":4},{"id":"155-19","rang":"A","rubrique":"Prise en charge","titre":"Connaître le principe du traitement d'une dermohypodermite bactérienne et la notion d'urgence médicochirurgicale dans les formes nécrosantes ; Dermohypodermite bactérienne non nécrosante : connaître le traitement (antibiothérapie recommandée et si allergie pénicilline, mesures complémentaires (adulte et enfant)","contenu":"<h4>DHB non nécrosante (<span class=\"kw-clinique\">érysipèle</span>)</h4>\n      <table >\n        <thead><tr><th>Situation</th><th><span class=\"kw-ttt\">Antibiothérapie</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>1ʳᵉ intention</strong></td><td><span class=\"kw-ttt\">Amoxicilline</span> pendant <span class=\"kw-chiffre\">7 jours</span> ; <span class=\"kw-bio\">PO si ambulatoire</span>, <span class=\"kw-bio\">IV si hospitalisation</span> puis relais PO ; posologie adaptée au poids</td></tr>\n          <tr><td><strong><span class=\"kw-ci\">Allergie</span> pénicilline</strong></td><td><span class=\"kw-ttt\">Pristinamycine</span> ou <span class=\"kw-ttt\">clindamycine</span></td></tr>\n          <tr><td><strong>Enfant</strong></td><td><span class=\"kw-ttt\">Amoxicilline-acide clavulanique</span></td></tr>\n          <tr><td><strong>Morsure animale</strong></td><td><span class=\"kw-ttt\">Amoxicilline-acide clavulanique</span> pendant <span class=\"kw-chiffre\">7 jours</span></td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Mesures associées :</strong> <span class=\"kw-ttt\">prévention antitétanique</span>, <span class=\"kw-ttt\">antalgiques (paracétamol)</span>, <span class=\"kw-ttt\">repos avec surélévation du membre</span>, <span class=\"kw-ttt\">contention veineuse</span> dès l'amélioration, <span class=\"kw-ttt\">anticoagulation</span> préventive si FR de thrombose.</li>\n        <li><strong>Critères d'<span class=\"kw-alerte\">hospitalisation</span> :</strong> âge <span class=\"kw-chiffre\">&gt; 75 ans</span> ou <span class=\"kw-chiffre\">&lt; 1 an</span>, <span class=\"kw-etio\">obésité</span> morbide, <span class=\"kw-def\">comorbidités</span>, <span class=\"kw-alerte\">signes de gravité</span>, absence d'amélioration en <span class=\"kw-chiffre\">24-72 h</span>, doute diagnostique, impossibilité de <span class=\"kw-def\">surveillance</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">⚠️ <span class=\"kw-ci\">PAS d'antibiothérapie locale</span>, <span class=\"kw-ci\">PAS d'AINS</span>, <span class=\"kw-ci\">PAS de corticoïdes</span>.</div>\n      <h4>DHB nécrosante / <span class=\"kw-alerte\">fasciite nécrosante</span> — <span class=\"kw-alerte\">urgence</span> médico-chirurgicale 🔥</h4>\n      <p><span class=\"kw-alerte\">Urgence vitale médico-chirurgicale</span> (<span class=\"kw-chiffre\">≈ 30 % de mortalité</span>) ; <span class=\"kw-def\">pronostic</span> lié à la <span class=\"kw-alerte\">précocité de la chirurgie</span> ; admission en <span class=\"kw-alerte\">soins intensifs</span>.</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Prise en charge</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Mesures générales</strong></td><td><span class=\"kw-ttt\">Réanimation</span> des défaillances d'organe ; traitement de la porte d'entrée ; <span class=\"kw-ttt\">prévention antitétanique</span> ; <span class=\"kw-ci\">arrêt des AINS</span></td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Antibiothérapie</span> IV forte dose</strong> (<span class=\"kw-chiffre\">14-21 j</span>)</td><td><strong>Membre / cervico-faciale :</strong> <span class=\"kw-ttt\">amoxicilline-acide clavulanique + clindamycine</span><br><strong>Abdomino-périnéale :</strong> <span class=\"kw-ttt\">pipéracilline-tazobactam</span> ou <span class=\"kw-ttt\">imipénème</span><br><strong><span class=\"kw-clinique\">Gangrène</span> de Fournier :</strong> <span class=\"kw-ttt\">pénicilline + métronidazole + aminoside</span><br><strong>Toxicomane IV :</strong> <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> ± <span class=\"kw-ttt\">vancomycine</span> (anti-SARM)</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Chirurgie</span></strong></td><td><span class=\"kw-ttt\">Mise à plat / excision des tissus nécrosés</span>, débridement, lavage (reprises itératives) ; amputation parfois ; <span class=\"kw-ttt\">colostomie/cystostomie de décharge</span> si forme périnéale</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 349 — Infection des parties molles</em></p>","frequence":9,"liens":[{"href":"https://radiopaedia.org/articles/fournier-gangrene","label":"Radiopaedia : Fournier Gangrene"}]},{"id":"155-20","rang":"A","rubrique":"Prise en charge","titre":"Savoir qu'il faut rechercher une porte d'entrée devant une dermohypodermite","contenu":"<p>Devant toute DHB, la <span class=\"kw-def\">porte d'entrée</span> doit être <strong>recherchée systématiquement</strong> (retrouvée dans <span class=\"kw-chiffre\">3/4 des cas</span>) et <span class=\"kw-ttt\">traitée</span> — c'est la clé de la prévention des récidives.</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Intertrigo interorteils</span> (<span class=\"kw-etio\">dermatophytique</span> ++ : principale porte d'entrée de l'<span class=\"kw-clinique\">érysipèle de jambe</span>).</li>\n        <li><span class=\"kw-clinique\">Plaies</span>, <span class=\"kw-clinique\">érosions traumatiques</span>.</li>\n        <li><span class=\"kw-clinique\">Ulcère de jambe</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\">💡 Prévention : <span class=\"kw-ttt\">sécher entre les orteils</span>, <span class=\"kw-ttt\">traiter les intertrigos</span>, <span class=\"kw-ttt\">désinfecter les plaies</span>, surveiller le <span class=\"kw-clinique\">pied diabétique</span>.</div>","frequence":0},{"id":"155-21","rang":"A","rubrique":"Physiopathologie","titre":"Connaître la définition et physiopathologie de l'anthrax et du furoncle","contenu":"<p>Infections du <span class=\"kw-def\">follicule pilo-sébacé</span> à <span class=\"kw-etio\">Staphylococcus aureus</span> (= <span class=\"kw-etio\">bactérie majoritaire</span>), favorisées par la <span class=\"kw-clinique\">macération</span> et les <span class=\"kw-clinique\">frottements</span> :</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition / <span class=\"kw-def\">physiopathologie</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Folliculite</span></strong></td><td>Infection <span class=\"kw-def\">superficielle</span> du follicule (<span class=\"kw-clinique\">ostium folliculaire</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Furoncle</span></strong></td><td>Infection <span class=\"kw-def\">profonde et nécrosante de l'ensemble du follicule pilo-sébacé</span> (le <span class=\"kw-clinique\">poil disparaît</span> dans la <span class=\"kw-clinique\">nécrose</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Anthrax</span></strong></td><td><span class=\"kw-def\">Conglomérat de plusieurs furoncles</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">💡 Le <span class=\"kw-clinique\">furoncle</span> mature un <span class=\"kw-clinique\">bourbillon</span> (cône de <span class=\"kw-clinique\">nécrose</span> central) en <span class=\"kw-chiffre\">5-10 jours</span> ; la répétition chronique = <span class=\"kw-clinique\">furonculose</span> (portage nasal de <span class=\"kw-etio\">S. aureus</span> à <span class=\"kw-bio\">leucocidine de Panton-Valentine</span>).</div>","frequence":1},{"id":"155-22","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques du furoncle","contenu":"<ul>\n        <li><span class=\"kw-clinique\">Apyrexie</span> (sauf forme <span class=\"kw-clinique\">profuse</span>/compliquée).</li>\n        <li><span class=\"kw-clinique\">Papule</span>/<span class=\"kw-clinique\">nodule inflammatoire douloureux</span>, centré par une <span class=\"kw-clinique\">pustule</span>, sur <span class=\"kw-clinique\">zone pileuse</span>.</li>\n        <li>Maturation en <span class=\"kw-chiffre\">5-10 jours</span> d'une <span class=\"kw-clinique\">zone nécrotique centrale</span> = <span class=\"kw-clinique\">bourbillon</span>.</li>\n        <li>Guérison avec <span class=\"kw-clinique\">cicatrice séquellaire</span>.</li>\n      </ul>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Diagnostic différentiel</span></th><th>Élément distinctif</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Kyste épidermique</strong> <span class=\"kw-etio\">inflammatoire</span>/surinfecté</td><td>Notion de <span class=\"kw-clinique\">kyste préexistant</span> (visage)</td></tr>\n          <tr><td><strong>Hidradénite suppurée</strong> (maladie de Verneuil)</td><td>Inflammation chronique des follicules dans les zones riches en <span class=\"kw-bio\">glandes apocrines</span> (axillaire, sous-mammaire, ano-périnéale)</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"155-23","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie de furoncle","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/155/furoncle.png\" alt=\"Furoncle : nodule inflammatoire douloureux centré par un bourbillon nécrotique\" loading=\"lazy\">\n        <figcaption><span class=\"kw-clinique\">Furoncle</span> : <span class=\"kw-clinique\">nodule inflammatoire</span> douloureux centré par une <span class=\"kw-clinique\">pustule</span> évoluant vers le <span class=\"kw-clinique\">bourbillon nécrotique</span>. Source : fiche source EDN item 155.</figcaption>\n      </figure>\n      <p>Reconnaître la <span class=\"kw-clinique\">lésion</span> : <span class=\"kw-clinique\">nodule érythémateux</span> <span class=\"kw-clinique\">centré par une pustule</span> sur une <span class=\"kw-clinique\">zone pileuse</span>, avec à maturation un <span class=\"kw-clinique\">bourbillon</span> (<span class=\"kw-clinique\">cône de nécrose central</span>).</p>\n      <ul>\n        <li><strong>Germe :</strong> <span class=\"kw-etio\">Staphylococcus aureus</span>.</li>\n        <li><strong>Maturation :</strong> <span class=\"kw-chiffre\">5-10 jours</span>, laisse une <span class=\"kw-clinique\">cicatrice</span>.</li>\n        <li><strong>Piège :</strong> un <span class=\"kw-clinique\">furoncle</span> <span class=\"kw-clinique\">centro-facial</span> manipulé expose à la <span class=\"kw-alerte\">staphylococcie maligne de la face</span>.</li>\n      </ul>","frequence":2},{"id":"155-24","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principes du traitement du furoncle","contenu":"<table >\n        <thead><tr><th>Situation</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Furoncle</span> isolé</strong></td><td><span class=\"kw-ci\">Pas d'antibiothérapie</span> — soins locaux uniquement : <span class=\"kw-ttt\">ne pas manipuler</span>, <span class=\"kw-ttt\">protéger par un pansement</span>, <span class=\"kw-ttt\">nettoyage eau + savon</span>, <span class=\"kw-ttt\">lavage des mains</span> ; <span class=\"kw-ttt\">incision</span> de l'extrémité si <span class=\"kw-clinique\">volumineux</span> (évacuer le <span class=\"kw-clinique\">bourbillon</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Furoncle</span> compliqué</strong><br>(<span class=\"kw-clinique\">anthrax</span>, <span class=\"kw-clinique\">DHB péri-lésionnelle</span>, <span class=\"kw-clinique\">lésions multiples</span>)</td><td><span class=\"kw-ttt\">Mesures d'hygiène rigoureuses</span> + <span class=\"kw-ttt\">ATB systémique PO</span> <span class=\"kw-chiffre\">5 jours</span> : <span class=\"kw-ttt\">pristinamycine</span> ou <span class=\"kw-ttt\">clindamycine</span> (<span class=\"kw-ttt\">augmentin</span> en pédiatrie) ; <span class=\"kw-ci\">pas d'ATB locale</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"155-25","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications du furoncle","contenu":"<p><strong>Staphylococcie maligne de la face</strong> 🔥 = complication redoutée :</p>\n      <ul>\n        <li>Complique un <span class=\"kw-clinique\">furoncle centro-facial</span> (zone canthus interne – commissure labiale – aile du nez), souvent après <span class=\"kw-clinique\">manipulation intempestive</span>.</li>\n        <li>Mécanisme : <span class=\"kw-clinique\">thrombophlébite superficielle septique</span>.</li>\n        <li>Tableau : <span class=\"kw-alerte\">fièvre brutale</span> + <span class=\"kw-alerte\">placard extensif/œdème du visage</span> ± cordon veineux induré.</li>\n        <li>Risque : <span class=\"kw-alerte\">thrombophlébite du sinus caverneux</span> (<span class=\"kw-alerte\">pronostic vital</span>).</li>\n        <li>Bilan : <span class=\"kw-imagerie\">TDM de la face sans injection</span> systématique. PEC : <span class=\"kw-ttt\">hospitalisation + ATB urgente + chirurgie</span>.</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/155/staphylococcie-maligne-face.png\" alt=\"Staphylococcie maligne de la face : placard inflammatoire extensif du visage compliquant un furoncle centro-facial\" loading=\"lazy\">\n        <figcaption>Staphylococcie maligne de la face compliquant un <span class=\"kw-clinique\">furoncle centro-facial</span>. Source : fiche source EDN item 155.</figcaption>\n      </figure>\n      <ul>\n        <li><strong>Autres complications :</strong> <span class=\"kw-clinique\">anthrax</span>, <span class=\"kw-clinique\">abcès</span>, <span class=\"kw-clinique\">furonculose</span> ; locorégionales (<span class=\"kw-clinique\">lymphangite</span>, <span class=\"kw-clinique\">DHB péri-lésionnelle</span>) ; systémiques (<span class=\"kw-alerte\">bactériémie</span>, <span class=\"kw-alerte\">endocardite</span>, <span class=\"kw-alerte\">infections ostéo-articulaires</span>).</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — Endocardite infectieuse</em></p>","frequence":1},{"id":"155-26","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Furonculose : connaître les facteurs favorisants, les examens à réaliser","contenu":"<p>La <span class=\"kw-def\">furonculose</span> = répétition chronique de furoncles (souvent multiples) pendant des mois/années.</p>\n      <ul>\n        <li><strong>Facteurs favorisants :</strong> <span class=\"kw-bio\">portage nasal persistant de S. aureus</span> sécréteur de <span class=\"kw-bio\">leucocidine de Panton-Valentine</span> ; ± <span class=\"kw-clinique\">diabète</span>, <span class=\"kw-clinique\">immunodépression</span>, <span class=\"kw-clinique\">carence martiale</span> (souvent absents).</li>\n        <li><strong>Examens :</strong> <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">glycémie à jeun</span>, <span class=\"kw-bio\">EPP</span>, <span class=\"kw-bio\">dépistage VIH</span>, <span class=\"kw-bio\">prélèvement bactériologique + antibiogramme</span> ; recherche des <span class=\"kw-bio\">gîtes de portage</span> (narines, périnée, anus) seulement <strong>après échec d'une 1ʳᵉ décolonisation</strong>.</li>\n        <li><strong>Décolonisation</strong> (<span class=\"kw-chiffre\">7 jours</span>, patient + entourage) : <span class=\"kw-ttt\">mupirocine nasale</span> 2×/j, <span class=\"kw-ttt\">chlorhexidine</span> (savon/shampooing), bains de bouche, hygiène du linge.</li>\n      </ul>","frequence":0},{"id":"155-27","rang":"A","rubrique":"Définition","titre":"Connaître la définition, la physiopathologie, l'épidémiologie de l'impétigo et de l'impétiginisation","contenu":"<table >\n        <thead><tr><th>Item</th><th>Données</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td>Infection de la <span class=\"kw-def\">couche cornée de l'épiderme</span>, <span class=\"kw-bio\">non immunisante</span> (récidives possibles)</td></tr>\n          <tr><td><strong>Germes</strong></td><td><span class=\"kw-etio\">S. aureus</span> dans <span class=\"kw-chiffre\">70-90 %</span> (France) ; <span class=\"kw-etio\">Streptocoque</span> dans <span class=\"kw-chiffre\">30 %</span> ; association possible</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span> / épidémio</strong></td><td>Infection <span class=\"kw-etio\">bactérienne</span> <span class=\"kw-clinique\">la plus fréquente chez l'enfant</span>, milieu défavorisé ; <span class=\"kw-clinique\">très contagieuse par manuportage</span> (épidémies intra-familiales/scolaires)</td></tr>\n          <tr><td><strong>Impétiginisation</strong></td><td><span class=\"kw-def\">Infection bactérienne d'une dermatose prurigineuse préexistante</span> ; <span class=\"kw-clinique\">forme principale de l'adulte</span> (<span class=\"kw-clinique\">impétigo</span> rarement primitif chez l'adulte)</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Dermatoses sous-jacentes :</strong> <span class=\"kw-etio\">eczéma</span>, <span class=\"kw-etio\">varicelle</span>, <span class=\"kw-etio\">lymphome cutané</span> ; lésions de grattage (<span class=\"kw-etio\">gale</span>, <span class=\"kw-etio\">pédiculose</span>).</li>\n        <li><strong><span class=\"kw-clinique\">Impétigo</span> bulleux :</strong> <span class=\"kw-etio\">S. aureus</span> producteur d'<span class=\"kw-bio\">exfoliatines A et B</span> ciblant la <span class=\"kw-bio\">desmogléine 1</span>.</li>\n      </ul>","frequence":0},{"id":"155-28","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d'un impétigo crouteux, d'un impétigo bulleux, d'une impétiginisation","contenu":"<p>Diagnostic <span class=\"kw-bio\">clinique</span> ; <span class=\"kw-clinique\">état général conservé, apyrexie</span>, ± <span class=\"kw-clinique\">adénopathie</span> satellite.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Présentation</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Impétigo</span> croûteux</strong></td><td><span class=\"kw-clinique\">Vésico-bulle</span> fragile → <span class=\"kw-clinique\">pustule</span> → <span class=\"kw-alerte\">rupture</span> → <span class=\"kw-clinique\">croûte mélicérique</span> jaunâtre (« miel cristallisé ») ; placards <span class=\"kw-clinique\">polycycliques</span> péri-orificiels ; guérison <span class=\"kw-clinique\">sans cicatrice</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Impétigo</span> bulleux</strong></td><td><span class=\"kw-clinique\">Bulles</span> par exfoliatines (desmogléine 1) ; surtout nouveau-né/nourrisson ; « pemphigus des crèches » péri-anal/génital</td></tr>\n          <tr><td><strong>Impétiginisation</strong></td><td>Croûtes mélicériques surajoutées à une <span class=\"kw-clinique\">dermatose prurigineuse</span> préexistante</td></tr>\n          <tr><td><strong>Ecthyma</strong> (forme creusante)</td><td><span class=\"kw-etio\">Streptocoque A</span>, sujets fragiles ; <span class=\"kw-clinique\">croûte noirâtre</span> + halo <span class=\"kw-etio\">inflammatoire</span> → <span class=\"kw-clinique\">ulcération</span> → cicatrice ; MI</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">💡 <span class=\"kw-bio\">Prélèvement bactériologique</span> (<span class=\"kw-clinique\">vésicule</span>/bulle non rompue) réservé aux cas compliqués/résistants/atypiques ou aux études épidémiologiques.</div>","frequence":0},{"id":"155-29","rang":"A","rubrique":"Contenu multimédia","titre":"Impétigo : photographies d'un impétigo crouteux, d'un impétigo bulleux, d'une impétiginisation)","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/155/impetigo-croutes-melicerique.png\" alt=\"Impétigo croûteux : croûtes mélicériques jaunâtres péri-orificielles\" loading=\"lazy\">\n        <figcaption><span class=\"kw-clinique\">Impétigo</span> croûteux : <span class=\"kw-clinique\">croûtes mélicériques</span> jaunâtres (« miel cristallisé »). Source : fiche source EDN item 155.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/155/impetigo-placards-polycycliques.png\" alt=\"Impétigo : lésions regroupées en placards polycycliques à contours circinés\" loading=\"lazy\">\n        <figcaption>Impétigo : lésions en <span class=\"kw-clinique\">placards polycycliques</span> à contours circinés. Source : fiche source EDN item 155.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/155/ecthyma-simple.png\" alt=\"Ecthyma simple : ulcération à croûte noirâtre, forme creusante de l'impétigo\" loading=\"lazy\">\n        <figcaption>Ecthyma simple (impétigo creusant) : <span class=\"kw-clinique\">croûte noirâtre</span> et <span class=\"kw-clinique\">ulcération</span>. Source : fiche source EDN item 155.</figcaption>\n      </figure>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Impétigo</span> croûteux :</strong> <span class=\"kw-clinique\">croûtes mélicériques</span> jaunâtres, placards <span class=\"kw-clinique\">polycycliques</span> péri-orificiels.</li>\n        <li><strong><span class=\"kw-clinique\">Impétigo</span> bulleux :</strong> <span class=\"kw-clinique\">bulles</span> fragiles sous-cornées (<span class=\"kw-bio\">exfoliatines</span>).</li>\n        <li><strong>Impétiginisation :</strong> croûtes surajoutées à une <span class=\"kw-clinique\">dermatose prurigineuse</span> préexistante.</li>\n        <li><strong>Ecthyma :</strong> <span class=\"kw-clinique\">croûte noirâtre</span> + <span class=\"kw-clinique\">ulcération</span> (forme creusante à <span class=\"kw-etio\">streptocoque A</span>).</li>\n      </ul>","frequence":2},{"id":"155-30","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement (adulte et enfant) : antibiothérapie et mesures complémentaires","contenu":"<table >\n        <thead><tr><th>Volet</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Hygiène</strong></td><td>Lavage bi-quotidien au savon, ongles courts, linge changé ; <span class=\"kw-ci\">pas d'antiseptiques locaux</span></td></tr>\n          <tr><td><strong>Éviction scolaire</strong></td><td><span class=\"kw-chiffre\">3 jours</span> si lésions non protégeables par un pansement</td></tr>\n          <tr><td><strong>Forme peu étendue</strong> (<span class=\"kw-chiffre\">&lt; 2 %</span> surface, <span class=\"kw-chiffre\">≤ 5-6</span> sites)</td><td><span class=\"kw-ttt\">Mupirocine locale</span> 2-3×/j pendant <span class=\"kw-chiffre\">5 jours</span></td></tr>\n          <tr><td><strong>Forme étendue / grave</strong></td><td>ATB systémique PO <span class=\"kw-chiffre\">7 jours</span> :<br><strong>Adulte :</strong> <span class=\"kw-ttt\">pristinamycine</span> ou <span class=\"kw-ttt\">céfalexine</span><br><strong>Enfant :</strong> <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> ou <span class=\"kw-ttt\">céfadroxil</span> ou <span class=\"kw-ttt\">josamycine</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">💡 Pas de nécessité de couvrir le <span class=\"kw-etio\">SARM</span> en 1ʳᵉ intention probabiliste.</div>","frequence":0},{"id":"155-31","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les modalités du diagnostic des complications d'un impétigo","contenu":"<p>Les complications de l'<span class=\"kw-clinique\">impétigo</span> sont <span class=\"kw-clinique\">exceptionnelles</span> (l'enjeu est surtout la <span class=\"kw-clinique\">contagion</span>) :</p>\n      <ul>\n        <li><strong>Formes graves :</strong> <span class=\"kw-clinique\">ecthyma</span>, atteinte <span class=\"kw-chiffre\">&gt; 2 %</span> de la surface, <span class=\"kw-chiffre\">&gt; 6 lésions</span>, <span class=\"kw-clinique\">extension rapide</span>.</li>\n        <li><strong>Locales :</strong> <span class=\"kw-clinique\">lymphangite</span>, <span class=\"kw-clinique\">abcès sous-cutané</span>.</li>\n        <li><strong>Systémiques (exceptionnelles) :</strong> <span class=\"kw-alerte\">rhumatisme articulaire aigu</span> ; <span class=\"kw-alerte\">glomérulonéphrite aiguë post-streptococcique</span> → <span class=\"kw-def\">dépistage</span> par <span class=\"kw-bio\">protéinurie</span> <span class=\"kw-chiffre\">3 semaines</span> après l'<span class=\"kw-clinique\">infection streptococcique</span>.</li>\n      </ul>","frequence":0},{"id":"155-32","rang":"A","rubrique":"Définition","titre":"Connaître la définition et la physiopathologie de la folliculite","contenu":"<p>La <span class=\"kw-def\">folliculite</span> est une <span class=\"kw-def\">infection superficielle du follicule pilo-sébacé</span> (<span class=\"kw-clinique\">ostium folliculaire</span>), majoritairement à <span class=\"kw-etio\">Staphylococcus aureus</span>.</p>\n      <ul>\n        <li><strong>Facteurs favorisants :</strong> <span class=\"kw-clinique\">macération</span>, <span class=\"kw-clinique\">frottements</span>, <span class=\"kw-clinique\">rasage</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Lésion</span> :</strong> atteinte de l'<span class=\"kw-clinique\">ostium folliculaire</span>, sans extension profonde (<span class=\"kw-bio\">vs</span> <span class=\"kw-clinique\">furoncle</span>).</li>\n      </ul>\n      <div class=\"callout callout-info\">💡 <span class=\"kw-def\">Physiopathologie</span> : <span class=\"kw-bio\">colonisation staphylococcique</span> de l'<span class=\"kw-clinique\">ostium</span> favorisée par l'<span class=\"kw-clinique\">occlusion</span> et la <span class=\"kw-clinique\">macération</span> ; reste <span class=\"kw-def\">superficielle</span> (≠ atteinte profonde du <span class=\"kw-clinique\">furoncle</span>).</div>","frequence":0},{"id":"155-33","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques de la folliculite","contenu":"<ul>\n        <li><span class=\"kw-clinique\">Papules érythémateuses</span> évoluant vers des <span class=\"kw-clinique\">pustules</span>, <span class=\"kw-clinique\">centrées par un poil</span>, avec <span class=\"kw-clinique\">érythème péri-folliculaire</span> ; <span class=\"kw-clinique\">ne laissent pas de cicatrice</span>.</li>\n        <li><strong>Localisations :</strong> <span class=\"kw-clinique\">zones pileuses</span> (cuisses, périnée, bras, thorax, dos) et de <span class=\"kw-clinique\">frottement</span>.</li>\n        <li><strong>Formes topographiques :</strong> <span class=\"kw-clinique\">sycosis</span> = <span class=\"kw-clinique\">folliculite</span> des <span class=\"kw-clinique\">poils durs de la barbe/pubis</span> (rasage) ; <span class=\"kw-clinique\">orgelet</span> = folliculite centrée sur un <span class=\"kw-clinique\">cil</span>.</li>\n      </ul>","frequence":0},{"id":"155-34","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la folliculite","contenu":"<p>Guérison <span class=\"kw-clinique\">spontanée</span> le plus souvent :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Éviter les sous-vêtements synthétiques</span> (<span class=\"kw-clinique\">macération</span>), douche quotidienne, vêtements propres.</li>\n        <li><span class=\"kw-ttt\">Antiseptiques topiques pluriquotidiens</span> : <span class=\"kw-ttt\">chlorhexidine</span>, <span class=\"kw-ttt\">polyvidone iodée</span>.</li>\n        <li><span class=\"kw-clinique\">Sycosis</span> : <span class=\"kw-ttt\">mousse à raser antiseptique</span>, <span class=\"kw-ttt\">rasoirs jetables</span>, espacer les rasages.</li>\n        <li><strong>Forme profuse seulement :</strong> <span class=\"kw-ttt\">amoxicilline-acide clavulanique PO</span> (ou <span class=\"kw-ttt\">pristinamycine</span> si <span class=\"kw-ci\">allergie</span>) pendant <span class=\"kw-chiffre\">7-10 jours</span>.</li>\n      </ul>","frequence":0},{"id":"155-35","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie de folliculite","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/155/folliculite-superficielle.png\" alt=\"Folliculite superficielle : pustules centrées par un poil avec érythème péri-folliculaire\" loading=\"lazy\">\n        <figcaption><span class=\"kw-clinique\">Folliculite</span> superficielle : <span class=\"kw-clinique\">pustules centrées par un poil</span> avec <span class=\"kw-clinique\">érythème péri-folliculaire</span>. Source : fiche source EDN item 155.</figcaption>\n      </figure>\n      <p>Reconnaître : <span class=\"kw-clinique\">pustules folliculaires</span> multiples, chacune <span class=\"kw-clinique\">traversée par un poil</span>, sur <span class=\"kw-clinique\">zone pileuse</span> ou de <span class=\"kw-clinique\">frottement</span>.</p>\n      <ul>\n        <li><strong>Germe :</strong> <span class=\"kw-etio\">Staphylococcus aureus</span> ; infection <span class=\"kw-def\">superficielle</span> (ostium).</li>\n        <li><strong>Formes :</strong> <span class=\"kw-clinique\">sycosis</span> (barbe), <span class=\"kw-clinique\">orgelet</span> (cil).</li>\n        <li><strong><span class=\"kw-bio\">vs</span> <span class=\"kw-clinique\">furoncle</span> :</strong> pas de <span class=\"kw-clinique\">nodule profond</span> ni de <span class=\"kw-clinique\">bourbillon</span>.</li>\n      </ul>","frequence":0},{"id":"155-36","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications possibles des folliculites","contenu":"<ul>\n        <li><span class=\"kw-clinique\">Évolution</span> vers un <span class=\"kw-clinique\">furoncle</span> puis une <span class=\"kw-clinique\">furonculose</span> (selon profondeur de l'atteinte folliculaire).</li>\n        <li>Formes <span class=\"kw-etio\">fongiques</span> (<span class=\"kw-etio\">dermatophytes</span> : <span class=\"kw-clinique\">kérion</span> ; <span class=\"kw-clinique\">folliculite</span> <span class=\"kw-etio\">pityrosporique</span> ; <span class=\"kw-etio\">Candida</span>) ou à <span class=\"kw-etio\">BGN</span> à évoquer si <span class=\"kw-clinique\">résistance</span>.</li>\n      </ul>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Diagnostic différentiel</span></th><th>Type</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Maladie de Behçet</span>, <span class=\"kw-etio\">maladie de Crohn</span></td><td>Pseudo-folliculites non infectieuses</td></tr>\n          <tr><td><span class=\"kw-etio\">Folliculite à éosinophiles</span></td><td>Pseudo-<span class=\"kw-clinique\">folliculite</span> non infectieuse</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">💡 Une <span class=\"kw-clinique\">folliculite</span> <span class=\"kw-clinique\">résistante aux antiseptiques</span> doit faire évoquer une cause <span class=\"kw-etio\">fongique</span> ou à <span class=\"kw-etio\">BGN</span> → <span class=\"kw-bio\">prélèvement</span> avant toute escalade.</div>","frequence":0},{"id":"155-37","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes physiopathologiques des cellulites faciales","contenu":"<p>Les <span class=\"kw-def\">cellulites faciales</span> ont <strong>2 portes d'entrée</strong> : <span class=\"kw-clinique\">bucco-dentaire (80 %)</span> ou <span class=\"kw-clinique\">cutanée</span>. Infection <span class=\"kw-bio\">polymicrobienne</span> (<span class=\"kw-etio\">aérobies</span> + <span class=\"kw-etio\">anaérobies</span>) ; les <span class=\"kw-etio\">anaérobies</span> produisent des <span class=\"kw-bio\">enzymes protéolytiques et des gaz</span> qui « dissèquent » les <span class=\"kw-clinique\">espaces cellulo-graisseux</span> → diffusion <span class=\"kw-clinique\">submandibulaire</span> puis <span class=\"kw-clinique\">cervicale</span> puis <span class=\"kw-alerte\">médiastinale</span>.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/155/anatomie-dent.webp\" alt=\"Schéma de l'anatomie d'une dent normale : couronne, racine, pulpe, parodonte\" loading=\"lazy\">\n        <figcaption>Anatomie d'une dent : <span class=\"kw-clinique\">couronne</span> (émail/dentine), <span class=\"kw-clinique\">racine</span> (cément), <span class=\"kw-clinique\">pulpe</span> (paquet vasculo-nerveux), <span class=\"kw-clinique\">parodonte</span> (tissu de soutien). Source : fiche source EDN item 155.</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th>Voie</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Endodontique</strong> (chambre pulpaire)</td><td><span class=\"kw-clinique\">Carie</span> → <span class=\"kw-clinique\">pulpite</span> → <span class=\"kw-clinique\">nécrose pulpaire</span> → <span class=\"kw-clinique\">granulome / kyste apical</span> (foyer <span class=\"kw-etio\">infectieux</span> chronique)</td></tr>\n          <tr><td><strong>Parodontale</strong> (collet, parodonte)</td><td><span class=\"kw-clinique\">Parodontopathie</span> chronique → foyer <span class=\"kw-etio\">infectieux</span> apical</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">💡 La cellulite gagne les parties molles à partir d'une <span class=\"kw-clinique\">ostéite</span> péri-apicale, traverse le périoste (<span class=\"kw-clinique\">abcès</span> sous-périosté → sous-muqueux) puis diffuse par les espaces de décollement et par <span class=\"kw-clinique\">emboles septiques</span>.</div>","frequence":0},{"id":"155-38","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d'une cellulite faciale collectée et séreuse","contenu":"<p>Les cellulites faciales aiguës évoluent en stades. Le grand discriminant clinique = la <span class=\"kw-clinique\">fluctuation</span>.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Signes cliniques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Séreuse</strong> (non collectée, début)</td>\n            <td>Signes de la porte d'entrée (<span class=\"kw-clinique\">desmodontite</span>) ; <span class=\"kw-clinique\">tuméfaction douloureuse aux limites imprécises</span> comblant le sillon ; <span class=\"kw-clinique\">peau d'abord normale</span> puis <span class=\"kw-clinique\">tendue/chaude</span> ; ± <span class=\"kw-clinique\">trismus</span> ; <span class=\"kw-bio\">PAS de fluctuation à la palpation</span> (sans collection)</td>\n          </tr>\n          <tr>\n            <td><strong>Collectée</strong> (suppurée)</td>\n            <td><span class=\"kw-clinique\">Fluctuation au palper bidigital</span> (signe la <span class=\"kw-clinique\">collection</span>) ; <span class=\"kw-clinique\">peau rouge/tendue/luisante</span>, <span class=\"kw-clinique\">masse adhérente au plan osseux</span> ; <span class=\"kw-clinique\">douleur intense, continue, lancinante, nocturne</span>, insomniante ; <span class=\"kw-clinique\">trismus</span> marqué ; ± <span class=\"kw-alerte\">dysphagie</span>, <span class=\"kw-alerte\">dyspnée</span> (gravité)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">💡 La collection peut ne pas être palpable si elle est très profonde ou postérieure.</div>","frequence":2},{"id":"155-39","rang":"B","rubrique":"Etiologie","titre":"Connaître les différentes portes d'entrée d'une cellulite de la face","contenu":"<ul>\n        <li><strong>Bucco-dentaire (<span class=\"kw-chiffre\">80 %</span>)</strong> :\n          <ul>\n            <li><span class=\"kw-etio\">Foyer apical</span> : <span class=\"kw-clinique\">granulome</span> ou <span class=\"kw-clinique\">kyste apical</span> ;</li>\n            <li><span class=\"kw-etio\">Parodontopathie</span> ;</li>\n            <li><span class=\"kw-etio\">Péricoronarite</span> (<span class=\"kw-clinique\">éruption</span> de la <span class=\"kw-clinique\">dent de sagesse</span>) ;</li>\n            <li><span class=\"kw-etio\">Traumatisme dentaire</span>.</li>\n          </ul>\n        </li>\n        <li><strong>Cutanée</strong> : <span class=\"kw-clinique\">érysipèle de la face</span> (<span class=\"kw-etio\">streptocoque</span>), ou complication d'un <span class=\"kw-etio\">furoncle centro-facial</span> (<span class=\"kw-alerte\">staphylococcie maligne</span>).</li>\n      </ul>\n      <div class=\"callout callout-info\">💡 Dents causales = surtout les <span class=\"kw-clinique\">molaires</span> (ordre de fréquence : <span class=\"kw-chiffre\">1ʳᵉ &gt; 3ᵉ &gt; 2ᵉ molaire</span>, puis prémolaires, canines, incisives) ; infection <span class=\"kw-bio\">polymicrobienne</span> aéro-anaérobie.</div>","frequence":0},{"id":"155-40","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens de première intention","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Modalités / intérêt</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Biologie</strong></td><td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">bilan d'hémostase</span> (vue d'un <span class=\"kw-ttt\">drainage</span> sous AG) ; <span class=\"kw-bio\">hémocultures</span> si <span class=\"kw-clinique\">fièvre</span> &gt; <span class=\"kw-chiffre\">38,5 °C</span>/<span class=\"kw-alerte\">sepsis</span></td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Orthopantomogramme</span></strong></td><td>Identifie la <span class=\"kw-imagerie\">dent causale</span> (carie, granulome, kyste, parodontopathie) ; ne doit pas retarder la PEC ; non indiqué si forme collectée/grave</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">TDM</span> cervico-faciale injectée</strong></td><td>Si <span class=\"kw-clinique\">cellulite collectée</span>, <span class=\"kw-clinique\">trismus</span> ou <span class=\"kw-alerte\">signes de gravité</span> ; <span class=\"kw-imagerie\">collection = hypodensité à prise de contraste périphérique</span> ; recherche extension médiastinale</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"155-41","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes de gravité d'une cellulite faciale et complications graves","contenu":"<p>La constatation d'<strong>un seul</strong> de ces signes impose l'<span class=\"kw-alerte\">hospitalisation en urgence</span> :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Sepsis / choc septique</span>, <span class=\"kw-clinique\">AEG</span>, déshydratation.</li>\n        <li><span class=\"kw-alerte\">Érythème extensif</span> vers le cou / les creux sus-claviculaires / le sternum.</li>\n        <li><span class=\"kw-alerte\">Crépitations sous-cutanées</span>.</li>\n        <li><span class=\"kw-alerte\">Tuméfaction du plancher buccal / œdème lingual</span> (risque d'obstruction des VAS).</li>\n        <li><span class=\"kw-alerte\">Dysphagie</span>, <span class=\"kw-alerte\">dyspnée</span>, <span class=\"kw-alerte\">dysphonie</span>, <span class=\"kw-alerte\">trismus serré</span>.</li>\n        <li><span class=\"kw-alerte\">Cordon induré du sillon nasogénien</span> jusqu'au canthus interne (thrombophlébite faciale).</li>\n        <li><strong>Scanographiques :</strong> <span class=\"kw-imagerie\">médiastinite</span>, <span class=\"kw-imagerie\">emphysème</span>, <span class=\"kw-imagerie\">collection profonde</span>, <span class=\"kw-ttt\">réduction</span> de la filière respiratoire.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Complication grave</th><th>Mécanisme / risque</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Thrombophlébite faciale / sinus caverneux</strong></td><td><span class=\"kw-clinique\">Œdème</span> du canthus interne, exophtalmie, atteinte des nerfs III-IV-VI ; <span class=\"kw-alerte\">pronostic vital</span></td></tr>\n          <tr><td><strong>Médiastinite</strong></td><td>Diffusion cervicale jusqu'au médiastin ; PEC chirurgicale en double équipe</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Détresse</span> respiratoire</strong></td><td>Obstruction des VAS (collection pharyngée)</td></tr>\n          <tr><td><strong>Endocardite infectieuse</strong></td><td>Foyer dentaire = cause fréquente d'EI (bactériémie)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — Endocardite infectieuse · 349 — Infection des parties molles</em></p>","frequence":2},{"id":"155-42","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes thérapeutiques des cellulites faciales","contenu":"<table >\n        <thead><tr><th>Volet</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">Chirurgie</span> (forme collectée)</strong></td><td><span class=\"kw-ttt\">Drainage chirurgical</span> (incision + évacuation du pus + lavage) ; zone laissée <span class=\"kw-ttt\">ouverte</span> (pas de suture) pour éviter la récidive</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Antibiothérapie</span></strong></td><td><span class=\"kw-ttt\">ATB probabiliste</span> puis adaptée (ex. <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> + <span class=\"kw-ttt\">pristinamycine</span>/<span class=\"kw-ttt\">clindamycine</span> + <span class=\"kw-ttt\">métronidazole</span>)</td></tr>\n          <tr><td><strong>Porte d'entrée dentaire</strong></td><td>Traitement de la <span class=\"kw-ttt\">dent causale</span> toujours nécessaire (éviter <span class=\"kw-clinique\">chronicisation</span>/<span class=\"kw-clinique\">récidive</span>)</td></tr>\n          <tr><td><strong>Symptomatique</strong></td><td><span class=\"kw-ttt\">Antalgiques adaptés</span> ; application de froid</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">⚠️ <span class=\"kw-ci\">Proscrire AINS et corticoïdes</span> (favorisent l'extension/la <span class=\"kw-alerte\">fasciite nécrosante</span>).</div>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Hospitalisation</span></strong> si <span class=\"kw-alerte\">signes de gravité</span> généraux/fonctionnels, localisation profonde à risque, <span class=\"kw-def\">terrain</span> fragile, <span class=\"kw-ttt\">drainage</span> sous AG, ou <span class=\"kw-clinique\">évolution</span> péjorative.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 349 — Infection des parties molles</em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Dermohypodermite nécrosante / fasciite :</strong> <span class=\"kw-alerte\">urgence vitale médico-chirurgicale</span> (<span class=\"kw-chiffre\">30 % de mortalité</span>), <span class=\"kw-def\">pronostic</span> lié à la <span class=\"kw-alerte\">rapidité de prise en charge</span> → <span class=\"kw-ttt\">admission en USI</span>.<br><strong>Premier geste :</strong> <span class=\"kw-ttt\">marquer le contour de l'érythème au feutre</span>, <span class=\"kw-ttt\">appel chirurgical</span> immédiat et <span class=\"kw-ci\">arrêt des AINS</span>.<br><strong>Staphylococcie maligne de la face :</strong> <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-alerte\">risque de thrombophlébite du sinus caverneux</span>) → <span class=\"kw-ttt\">hospitalisation + ATB + chirurgie</span>.<br><strong><span class=\"kw-clinique\">Cellulite faciale</span> collectée :</strong> <span class=\"kw-ttt\">drainage chirurgical</span> en <span class=\"kw-alerte\">urgence</span> + <span class=\"kw-ttt\">antibiothérapie IV</span>.</p>","hospit":"<p><strong><span class=\"kw-clinique\">Érysipèle</span> :</strong> traitement <span class=\"kw-ttt\">ambulatoire</span> dans la majorité des cas (<span class=\"kw-ttt\">amoxicilline per os</span>).<br><strong><span class=\"kw-alerte\">Hospitalisation</span> si :</strong> âge <span class=\"kw-chiffre\">> 75 ans</span> ou <span class=\"kw-chiffre\">< 1 an</span>, <span class=\"kw-clinique\">obésité morbide</span>, risque de <span class=\"kw-alerte\">décompensation</span> de comorbidités, <span class=\"kw-alerte\">signes de gravité</span>, <span class=\"kw-alerte\">absence d'amélioration en 24-72 h</span> ou <span class=\"kw-alerte\">extension sous traitement</span>, doute diagnostique, surveillance impossible à domicile.<br><strong>Forme nécrosante :</strong> <span class=\"kw-ttt\">USI / réanimation</span> + <span class=\"kw-ttt\">exploration chirurgicale</span>.<br><strong>Cellulite faciale :</strong> hospitalisation si <span class=\"kw-alerte\">signes de gravité</span> (<span class=\"kw-alerte\">dysphagie</span>, <span class=\"kw-alerte\">dyspnée</span>, <span class=\"kw-alerte\">trismus serré</span>), localisation profonde ou <span class=\"kw-ttt\">drainage sous anesthésie générale</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Douleur intense disproportionnée</span> s'étendant au-delà des zones inflammatoires, <span class=\"kw-alerte\">non soulagée par les antalgiques de palier 1 ou 2</span></li><li><span class=\"kw-alerte\">Extension rapide</span>, ou extension des lésions <span class=\"kw-alerte\">malgré une antibiothérapie bien conduite</span></li><li><span class=\"kw-clinique\">Induration des tissus dépassant l'érythème visible</span></li><li><span class=\"kw-alerte\">Nécrose locale</span> : <span class=\"kw-clinique\">lividités / zones livedoïdes</span>, <span class=\"kw-clinique\">taches cyaniques</span>, <span class=\"kw-clinique\">plaques noirâtres</span></li><li><span class=\"kw-alerte\">Bulles séro-hématiques ou hémorragiques</span></li><li><span class=\"kw-alerte\">Crépitation neigeuse</span> (présence de <span class=\"kw-etio\">germes anaérobies</span>)</li><li><span class=\"kw-clinique\">Écoulements fétides</span></li><li><span class=\"kw-alerte\">Anesthésie douloureuse</span> : <span class=\"kw-clinique\">placards grisâtres hypoesthésiques</span> (<span class=\"kw-def\">stade</span> tardif)</li><li><span class=\"kw-alerte\">Sepsis</span> : <span class=\"kw-chiffre\">qSOFA ≥ 2</span> (<span class=\"kw-chiffre\">FR ≥ 22/min</span>, <span class=\"kw-chiffre\">PAS ≤ 100 mmHg</span>, <span class=\"kw-chiffre\">Glasgow < 15</span>), fièvre élevée ou hypothermie, frissons</li><li>Cellulite faciale : <span class=\"kw-alerte\">dysphagie</span>, <span class=\"kw-alerte\">dyspnée</span>, <span class=\"kw-alerte\">dysphonie</span>, <span class=\"kw-alerte\">trismus serré</span>, <span class=\"kw-alerte\">œdème du plancher buccal ou de la langue</span> (risque d'obstruction des VAS)</li><li>⚠️ NE sont PAS des <span class=\"kw-alerte\">signes de gravité</span> (présents dans l'<span class=\"kw-etio\">érysipèle non compliqué</span>) : <span class=\"kw-clinique\">phlyctène</span>, <span class=\"kw-clinique\">décollement bulleux</span>, <span class=\"kw-clinique\">purpura</span></li></ul>","principes":"<p>Infections à <span class=\"kw-etio\">cocci Gram +</span> (<span class=\"kw-etio\">Streptococcus pyogenes</span>, <span class=\"kw-etio\">Staphylococcus aureus</span>) : toujours <span class=\"kw-clinique\">rechercher et traiter la porte d'entrée</span> ; <span class=\"kw-ci\">jamais d'AINS ni de corticoïdes</span>.</p><p><strong><span class=\"kw-clinique\">Érysipèle</span> (DHB non nécrosante)</strong></p><p>Recherche et traitement de la porte d'entrée (<span class=\"kw-etio\">intertrigo inter-orteils</span> ++)</p><ul><li><span class=\"kw-ttt\">Amoxicilline</span> pendant <span class=\"kw-chiffre\">7 jours</span> (<span class=\"kw-ttt\">per os</span> si ambulatoire, <span class=\"kw-ttt\">IV</span> si <span class=\"kw-alerte\">hospitalisation</span> puis relais per os), posologie adaptée au poids</li><li><span class=\"kw-ci\">Allergie</span> à la pénicilline : <span class=\"kw-ttt\">pristinamycine</span> ou <span class=\"kw-ttt\">clindamycine</span></li><li>Enfant : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> ; morsure animale : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> <span class=\"kw-chiffre\">7 jours</span></li><li>Mesures : <span class=\"kw-ttt\">prévention anti-tétanique</span>, <span class=\"kw-ttt\">antalgique (paracétamol)</span>, repos + surélévation du membre, <span class=\"kw-ttt\">contention</span> dès amélioration de la douleur</li><li>À proscrire : <span class=\"kw-ci\">AINS</span>, <span class=\"kw-ci\">corticoïdes</span>, <span class=\"kw-ci\">antibiothérapie locale</span></li></ul><p><strong>DHB nécrosante / <span class=\"kw-alerte\">fasciite nécrosante</span></strong></p><p>Forme périnéale : <span class=\"kw-ttt\">colostomie / dérivation urinaire de décharge</span></p><ul><li><span class=\"kw-alerte\">Urgence médico-chirurgicale</span> : <span class=\"kw-alerte\">réanimation</span>, prise en charge des défaillances d'organe, <span class=\"kw-ci\">arrêt des AINS</span>, <span class=\"kw-ttt\">prévention anti-tétanique</span></li><li><span class=\"kw-ttt\">Chirurgie précoce</span> (conditionne le <span class=\"kw-def\">pronostic</span>) : <span class=\"kw-ttt\">mise à plat, excision des tissus nécrosés, débridement, lavage</span>, reprise tant que la <span class=\"kw-clinique\">nécrose</span> réapparaît</li><li><span class=\"kw-ttt\">Antibiothérapie IV forte dose</span> pendant <span class=\"kw-chiffre\">14-21 jours</span> selon la localisation</li><li>Membres / cervico-faciale : <span class=\"kw-ttt\">Augmentin + Clindamycine</span></li><li>Abdomino-périnéale : <span class=\"kw-ttt\">pipéracilline-tazobactam ou imipénème</span></li><li><span class=\"kw-clinique\">Gangrène</span> de Fournier : <span class=\"kw-ttt\">pénicilline + métronidazole + aminosides</span></li></ul><p><strong><span class=\"kw-clinique\">Cellulite faciale</span> / <span class=\"kw-clinique\">abcès</span></strong></p><p>Traitement de la porte d'entrée = <span class=\"kw-ttt\">dent causale</span> (avis odontologiste)</p><ul><li><span class=\"kw-clinique\">Abcès</span> : <span class=\"kw-ttt\">drainage chirurgical</span> (incision, évacuation du pus, lavage), zone <span class=\"kw-ttt\">laissée ouverte</span> (pas de suture)</li><li>ATB probabiliste : <span class=\"kw-ttt\">Augmentin + Pristinamycine</span> ou <span class=\"kw-ttt\">Clindamycine + Métronidazole</span></li><li><span class=\"kw-ttt\">Antalgique</span>, application de froid ; <span class=\"kw-ci\">proscrire AINS et corticoïdes</span></li><li>Forme collectée / grave : <span class=\"kw-ttt\">hospitalisation, à jeun, ATB IV urgente, drainage sous anesthésie générale</span></li></ul><p><strong><span class=\"kw-clinique\">Folliculite</span>, furoncle & impétigo</strong></p><ul><li><span class=\"kw-clinique\">Furoncle</span> isolé : <span class=\"kw-ci\">pas d'antibiothérapie</span>, soins locaux (ne pas manipuler, protéger ; <span class=\"kw-ttt\">incision</span> si volumineux pour évacuer le bourbillon)</li><li><span class=\"kw-clinique\">Furoncle</span> compliqué (anthrax, lésions multiples) : <span class=\"kw-ttt\">pristinamycine ou clindamycine</span> per os <span class=\"kw-chiffre\">5 jours</span></li><li>Furonculose : ATB per os <span class=\"kw-chiffre\">7 jours</span> + <span class=\"kw-ttt\">décolonisation des gîtes</span> (<span class=\"kw-ttt\">mupirocine nasale</span>, <span class=\"kw-ttt\">chlorhexidine</span>) <span class=\"kw-chiffre\">7 jours</span>, patient et entourage</li><li><span class=\"kw-clinique\">Impétigo</span> peu étendu (<span class=\"kw-chiffre\">< 2 % de surface</span>, <span class=\"kw-chiffre\">≤ 5-6 sites</span>) : <span class=\"kw-ttt\">mupirocine topique</span> <span class=\"kw-chiffre\">5 jours</span></li><li>Impétigo étendu ou ecthyma : <span class=\"kw-ttt\">antibiothérapie per os</span> <span class=\"kw-chiffre\">7 jours</span> (<span class=\"kw-ttt\">pristinamycine / céfalexine</span> adulte ; <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> enfant) ; <span class=\"kw-clinique\">éviction scolaire 3 jours</span> si lésions non protégeables</li></ul>","suivi":"<p><strong><span class=\"kw-clinique\">Érysipèle</span> sous antibiotiques :</strong> l'<span class=\"kw-clinique\">apyrexie en 48-72 h</span> signe l'efficacité ; l'<span class=\"kw-clinique\">extension dans les 24 premières heures</span> est fréquente et normale ; régression du <span class=\"kw-clinique\">placard</span> et de l'<span class=\"kw-clinique\">œdème</span> en <span class=\"kw-chiffre\">1 à 3 semaines</span> (guérison en <span class=\"kw-chiffre\">8-10 jours</span>).<br><strong>Absence d'amélioration :</strong> suspecter un <span class=\"kw-etio\">abcès sous-cutané</span> (à inciser/drainer), une <span class=\"kw-alerte\">forme nécrosante à bas bruit</span> ou une <span class=\"kw-etio\">étiologie non streptococcique</span>.<br><strong>Forme nécrosante :</strong> <span class=\"kw-ttt\">surveillance quotidienne</span>, <span class=\"kw-ttt\">reprise chirurgicale</span> tant que des zones de <span class=\"kw-clinique\">nécrose</span> réapparaissent.<br><strong><span class=\"kw-def\">Prévention secondaire</span> :</strong> récidive d'érysipèle <span class=\"kw-chiffre\">20-30 %</span> ; si <span class=\"kw-chiffre\">≥ 2 épisodes/an</span> + échec des mesures primaires → <span class=\"kw-ttt\">antibioprophylaxie (benzathine benzylpénicilline G ou pénicilline V)</span> toutes les <span class=\"kw-chiffre\">2-3 semaines</span> pendant <span class=\"kw-chiffre\">≥ 6 mois</span>, contention + perte de poids.</p>"},"liensGlobaux":[{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/45.%20Infections%20cutan%C3%A9omuqueuses%20s%C3%A9v%C3%A8res.pdf","label":"Collège (MIR) — Infections cutanéo-muqueuses sévères"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Grosse jambe rouge aiguë fébrile — <span class=\"kw-clinique\">Placard inflammatoire unilatéral</span>, début brutal, <span class=\"kw-clinique\">fièvre</span>","detail":"<h4>CAT — Grosse jambe rouge aiguë fébrile — Orientation <span class=\"kw-clinique\">érysipèle</span> <span class=\"kw-bio\">vs</span> dermohypodermite <span class=\"kw-etio\">bactérienne</span> nécrosante</h4>","branches":[{"to":"q-gravite","label":"Évaluation initiale","color":"blue"}]},{"id":"q-gravite","kind":"decision","label":"<span class=\"kw-alerte\">Signes de gravité</span> ou de <span class=\"kw-clinique\">nécrose</span> ? — <span class=\"kw-alerte\">Douleur disproportionnée</span>, <span class=\"kw-alerte\">nécrose</span>, <span class=\"kw-alerte\">crépitation</span>, <span class=\"kw-alerte\">sepsis (qSOFA ≥ 2)</span>","branches":[{"to":"t-necrosante","label":"Oui : ≥ 1 signe de gravité","color":"red"},{"to":"q-hospit","label":"Non : érysipèle non compliqué","color":"green"}]},{"id":"t-necrosante","kind":"terminal","label":"DHB nécrosante / fasciite — <span class=\"kw-alerte\">urgence</span> médico-chirurgicale — <span class=\"kw-ttt\">USI + exploration chirurgicale</span>","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Admission en USI / réanimation</span> + <span class=\"kw-ttt\">appel chirurgical</span> en <span class=\"kw-alerte\">urgence</span></li><li><span class=\"kw-ttt\">Marquer le contour au feutre</span>, <span class=\"kw-ci\">arrêt des AINS</span>, <span class=\"kw-ttt\">prévention anti-tétanique</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hémocultures avant antibiothérapie</span>, <span class=\"kw-bio\">NFS, CRP, lactatémie, CPK, bilan d'hémostase</span></li><li>L'<span class=\"kw-imagerie\">imagerie</span> ne doit pas retarder la prise en charge</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antibiothérapie IV forte dose 14-21 jours</span> selon localisation (<span class=\"kw-ttt\">Augmentin + Clindamycine</span> aux membres)</li><li><span class=\"kw-ttt\">Chirurgie précoce</span> : excision des tissus nécrosés, débridement, lavage</li></ul>"},{"id":"q-hospit","kind":"decision","label":"Critères d'hospitalisation ? — Âges extrêmes, obésité morbide, comorbidités, doute, surveillance impossible","branches":[{"to":"t-hospit","label":"Oui","color":"amber"},{"to":"t-ambu","label":"Non","color":"green"}]},{"id":"t-hospit","kind":"terminal","label":"<span class=\"kw-clinique\">Érysipèle</span> hospitalisé — <span class=\"kw-ttt\">Amoxicilline IV</span>","color":"amber","detail":"<h4>Clinique</h4><ul><li>Critère présent : âge <span class=\"kw-chiffre\">> 75 ans</span> ou <span class=\"kw-chiffre\">< 1 an</span>, <span class=\"kw-clinique\">obésité morbide</span>, comorbidités décompensables, doute diagnostique ou surveillance impossible</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Amoxicilline IV</span> puis relais per os, <span class=\"kw-chiffre\">7 jours</span></li><li><span class=\"kw-ttt\">Antalgique</span> (<span class=\"kw-ci\">pas d'AINS ni de corticoïdes</span>), repos + surélévation, <span class=\"kw-ttt\">prévention anti-tétanique</span></li></ul>"},{"id":"t-ambu","kind":"terminal","label":"<span class=\"kw-clinique\">Érysipèle</span> en ambulatoire — <span class=\"kw-ttt\">Amoxicilline per os 7 jours</span>","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Amoxicilline per os 7 jours</span> (posologie adaptée au poids) ; <span class=\"kw-ttt\">pristinamycine</span> ou <span class=\"kw-ttt\">clindamycine</span> si <span class=\"kw-ci\">allergie</span></li><li>Traiter la porte d'entrée (<span class=\"kw-etio\">intertrigo</span>)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Réévaluer à <span class=\"kw-chiffre\">48-72 h</span> : <span class=\"kw-clinique\">apyrexie</span> attendue (extension dans les premières <span class=\"kw-chiffre\">24 h</span> normale)</li><li>Absence d'amélioration → suspecter <span class=\"kw-etio\">abcès</span>, <span class=\"kw-alerte\">forme nécrosante</span> ou <span class=\"kw-etio\">étiologie non streptococcique</span></li></ul>"}]},"cards":[{"i":"31001230f0ed","n":155,"o":"155-1","u":"Définition","t":"Connaître la définition d'une mycose superficielle","q":"Quelle est la définition d'une mycose superficielle ?","a":"<p>Une mycose superficielle est une infection à champignons limitée à la <strong>couche cornée de l'épiderme</strong>, aux <strong>phanères</strong> (poils, cheveux, ongles) et/ou aux <strong>muqueuses</strong>, sans envahissement profond.</p>"},{"i":"7375a53dbbf7","n":155,"o":"155-1","u":"Définition","t":"Connaître la définition d'une mycose superficielle","q":"Quelles sont les caractéristiques de Candida albicans dans le contexte des mycoses superficielles ?","a":"<ul><li>C'est un saprophyte des <strong>muqueuses digestives/génitales</strong>.</li><li>Il est pathogène opportuniste sous l'influence de facteurs favorisants.</li><li>Il est toujours <strong>pathogène en site cutané</strong> mais un simple saprophyte en site muqueux digestif/génital, ce qui influence l'interprétation des cultures.</li></ul>"},{"i":"83e6887d8632","n":155,"o":"155-1","u":"Définition","t":"Connaître la définition d'une mycose superficielle","q":"Quelles sont les caractéristiques des dermatophytes dans les mycoses superficielles ?","a":"<ul><li>Ils sont toujours <strong>pathogènes</strong>.</li><li>Ils sont <strong>kératinophiles</strong>.</li><li>Ils ne sont jamais saprophytes.</li><li>Ils respectent les <strong>muqueuses</strong>.</li></ul>"},{"i":"bfa89d1e7979","n":155,"o":"155-1","u":"Définition","t":"Connaître la définition d'une mycose superficielle","q":"Quels sont les deux grands groupes d'agents responsables des mycoses superficielles ?","a":"<ul><li>Les <strong>champignons filamenteux</strong> (Dermatophytes)</li><li>Les <strong>levures</strong> (Candida albicans, Malassezia furfur)</li></ul>"},{"i":"61a881fa05a8","n":155,"o":"155-13","u":"Diagnostic positif","t":"Connaître les orientations diagnostiques d'une grosse jambe rouge aiguë","q":"Quels sont les éléments clés pour distinguer une thrombose veineuse profonde (TVP) d'un érysipèle devant une grosse jambe rouge aiguë ?","a":"<p>La thrombose veineuse profonde se caractérise par une jambe rouge/chaude, mais avec une <strong>douleur localisée au mollet</strong> et un <strong>contexte thrombogène</strong>. L'<strong>écho-doppler</strong> est l'examen clé pour confirmer le diagnostic de TVP.</p>"},{"i":"a17e8ae09e85","n":155,"o":"155-13","u":"Diagnostic positif","t":"Connaître les orientations diagnostiques d'une grosse jambe rouge aiguë","q":"Quels sont les arguments cliniques orientant vers un érysipèle (Dermo-Hypodermite Bactérienne non nécrosante) devant une grosse jambe rouge aiguë ?","a":"<ul><li>Une <strong>fièvre brutale</strong>.</li><li>Un <strong>placard inflammatoire unilatéral</strong>.</li><li>Une <strong>douleur</strong>.</li><li>La présence d'une <strong>porte d'entrée</strong>.</li></ul>"},{"i":"bca6f6d49f99","n":155,"o":"155-13","u":"Diagnostic positif","t":"Connaître les orientations diagnostiques d'une grosse jambe rouge aiguë","q":"Quels sont les signes d'alerte devant une grosse jambe rouge aiguë faisant suspecter une dermo-hypodermite bactérienne (DHB) nécrosante nécessitant une urgence chirurgicale ?","a":"<ul><li>Une <strong>douleur disproportionnée</strong> par rapport aux signes cliniques.</li><li>Une <strong>nécrose</strong>.</li><li>Un état de <strong>sepsis</strong>.</li><li>Une <strong>extension de la lésion malgré l'antibiothérapie</strong>.</li></ul>"},{"i":"c11e819c4237","n":155,"o":"155-13","u":"Diagnostic positif","t":"Connaître les orientations diagnostiques d'une grosse jambe rouge aiguë","q":"Quelle est l'orientation diagnostique à évoquer en première intention devant une \"grosse jambe rouge aiguë\", notamment si elle est fébrile et unilatérale ?","a":"<p>Devant une grosse jambe rouge aiguë, le <strong>diagnostic d'érysipèle</strong> doit être évoqué en première intention, particulièrement s'il y a une <strong>fièvre brutale</strong> et un <strong>placard inflammatoire unilatéral douloureux</strong> avec une potentielle porte d'entrée.</p>"},{"i":"e36f3b82c014","n":155,"o":"155-13","u":"Diagnostic positif","t":"Connaître les orientations diagnostiques d'une grosse jambe rouge aiguë","q":"Comment différencier une cause non infectieuse (eczéma aigu, insuffisance veineuse) d'une étiologie infectieuse comme l'érysipèle face à une grosse jambe rouge aiguë ?","a":"<p>Les causes non infectieuses comme l'eczéma aigu ou la dermite de stase due à l'insuffisance veineuse sont souvent <strong>bilatérales</strong> et <strong>peu fébriles</strong>, alors qu'un érysipèle est généralement <strong>unilatéral et fébrile</strong>.</p>"},{"i":"0767fbfaa6b4","n":155,"o":"155-14","u":"Diagnostic positif","t":"Connaître les signes sémiologiques évocateurs de dermohypodermite bactérienne chez l'adulte et chez l'enfant","q":"Quel est le contexte de survenue fréquent d'une dermohypodermite bactérienne non nécrosante chez l'enfant et quel signe doit faire suspecter une forme grave d'érysipèle ?","a":"<p>Chez l'enfant, la dermohypodermite bactérienne non nécrosante (érysipèle) survient volontiers au décours d'une <strong>varicelle</strong>.</p><p>L'absence de signes de sepsis et de nécrose est attendue dans un érysipèle typique. Par conséquent, il est un <strong>drapeau rouge</strong> et doit faire suspecter une <strong>forme nécrosante</strong> si des signes de <strong>sepsis</strong> ou de <strong>nécrose</strong> sont présents.</p>"},{"i":"1bead6013b2b","n":155,"o":"155-14","u":"Diagnostic positif","t":"Connaître les signes sémiologiques évocateurs de dermohypodermite bactérienne chez l'adulte et chez l'enfant","q":"Quelles sont les particularités cliniques d'un érysipèle localisé au visage et quels signes ne sont pas considérés comme des critères de gravité ?","a":"<p>Au visage, l'érysipèle (dermohypodermite bactérienne non nécrosante) peut présenter :</p><ul><li>Un <strong>bourrelet périphérique</strong> (limite nette et surélevée).</li><li>Des <strong>croûtes</strong>.</li><li>Des <strong>pustules</strong>.</li></ul><p>Les signes suivants, bien que présents, ne sont <strong>pas des critères de gravité</strong> :</p><ul><li>Un <strong>décollement bulleux superficiel</strong> (dû à l'œdème dermique).</li><li>Un <strong>purpura localisé</strong> sur le placard.</li></ul>"},{"i":"95fda01550af","n":155,"o":"155-14","u":"Diagnostic positif","t":"Connaître les signes sémiologiques évocateurs de dermohypodermite bactérienne chez l'adulte et chez l'enfant","q":"Quels sont les signes généraux et les signes associés pouvant être présents lors d'un érysipèle (dermohypodermite bactérienne non nécrosante) chez l'adulte ?","a":"<p>Les signes généraux typiques d'un érysipèle incluent :</p><ul><li>Une <strong>fièvre brutale et élevée (39-40°C)</strong>, pouvant être précédée de <strong>frissons</strong>, souvent quelques heures avant les lésions cutanées.</li></ul><p>Les signes associés, inconstants mais fréquents, sont :</p><ul><li>Une <strong>adénopathie satellite</strong>.</li><li>Une <strong>lymphangite</strong>.</li></ul>"},{"i":"9fff2b921978","n":155,"o":"155-14","u":"Diagnostic positif","t":"Connaître les signes sémiologiques évocateurs de dermohypodermite bactérienne chez l'adulte et chez l'enfant","q":"Quels sont les signes cliniques du placard inflammatoire typique d'un érysipèle chez l'adulte ?","a":"<p>Un érysipèle se manifeste par un placard inflammatoire caractéristique, présentant les signes suivants :</p><ul><li><strong>Rouge</strong></li><li><strong>Chaud</strong></li><li><strong>Oedémateux</strong></li><li><strong>Douloureux</strong></li><li><strong>Unilatéral</strong></li><li>Début <strong>brutal</strong> avec une extension <strong>rapide</strong> (il est recommandé de <strong>marquer les contours au feutre</strong> pour suivre l'extension).</li></ul>"},{"i":"1603f1221a39","n":155,"o":"155-15","u":"Diagnostic positif","t":"Connaître les localisations les plus fréquentes de dermohypodermite bactérienne non nécrosante et nécrosantes","q":"Quelles sont les localisations les plus fréquentes des dermohypodermites bactériennes nécrosantes ?","a":"<p>Les localisations les plus fréquentes des dermohypodermites bactériennes nécrosantes sont :</p><ul><li>Les <strong>membres inférieurs</strong> (le plus souvent).</li><li>La région <strong>cervico-faciale</strong>, avec un risque de médiastinite.</li><li>La région <strong>thoraco-abdominale</strong>.</li><li>La région <strong>périnéale</strong>, appelée <strong>gangrène de Fournier</strong>.</li></ul>"},{"i":"4ac2798ce91c","n":155,"o":"155-15","u":"Diagnostic positif","t":"Connaître les localisations les plus fréquentes de dermohypodermite bactérienne non nécrosante et nécrosantes","q":"Dans quel contexte une dermohypodermite bactérienne non nécrosante peut-elle affecter le membre supérieur ou le thorax ?","a":"<p>Une dermohypodermite bactérienne non nécrosante peut toucher :</p><ul><li>Le <strong>membre supérieur</strong> en cas d'antécédent de <strong>curage ganglionnaire</strong>.</li><li>Le <strong>thorax</strong> en cas d'antécédent de <strong>thoracotomie</strong>.</li></ul>"},{"i":"58d68a3f4997","n":155,"o":"155-15","u":"Diagnostic positif","t":"Connaître les localisations les plus fréquentes de dermohypodermite bactérienne non nécrosante et nécrosantes","q":"Où se localise principalement l'érysipèle (dermohypodermite bactérienne non nécrosante) ?","a":"<p>L'érysipèle se localise principalement :</p><ul><li>Aux <strong>membres inférieurs</strong> (90% des cas).</li><li>Au <strong>visage</strong> (5-10% des cas), pouvant être une <strong>staphylococcie maligne</strong> si <em>Staphylococcus aureus</em> est en cause.</li></ul>"},{"i":"bef6acfbc3e3","n":155,"o":"155-16","u":"Identifier une urgence","t":"Connaître les signes de gravité d'une dermohypodermite","q":"Quels sont les signes cliniques de gravité devant faire suspecter une dermohypodermite nécrosante ou une fasciite nécrosante ?","a":"<p>Devant une dermohypodermite, les signes cliniques de gravité sont :</p><ul><li>une <strong>douleur intense</strong> dépassant les zones inflammatoires, non calmée par les antalgiques de palier 1-2 ;</li><li>une <strong>extension rapide</strong> des lésions malgré une antibiothérapie bien conduite ;</li><li>une <strong>induration des tissus</strong> au-delà de l'érythème visible ;</li><li>une <strong>crépitation neigeuse</strong> à la palpation (suggérant des germes anaérobies) ;</li><li>une <strong>nécrose cutanée</strong> visible : zones livedoïdes, taches cyaniques, plaques noirâtres ;</li><li>la présence de <strong>bulles séro-hématiques ou hémorragiques</strong> ;</li><li>un <strong>écoulement fétide</strong> ;</li><li>une <strong>hypoesthésie tardive</strong> (anesthésie douloureuse) ;</li><li>des signes de <strong>sepsis</strong> : par exemple un score qSOFA ≥ 2 (fréquence respiratoire ≥ 22/min, pression artérielle systolique ≤ 100 mmHg, Glasgow &lt; 15).</li></ul>"},{"i":"ce90b2049fbd","n":155,"o":"155-16","u":"Identifier une urgence","t":"Connaître les signes de gravité d'une dermohypodermite","q":"Quels signes cutanés sont particulièrement évocateurs d'une dermohypodermite nécrosante à streptocoque du groupe A ?","a":"<p>Une <strong>nécrose cutanée</strong> et des <strong>zones livedoïdes</strong> sont particulièrement évocateurs d'une dermohypodermite nécrosante à streptocoque du groupe A.</p>"},{"i":"f6c15c55db65","n":155,"o":"155-16","u":"Identifier une urgence","t":"Connaître les signes de gravité d'une dermohypodermite","q":"Quels signes ne sont PAS des signes de gravité dans le cadre d'une dermohypodermite, bien que parfois impressionnants ?","a":"<p>Contrairement à ce que l'on pourrait penser, la présence de <strong>phlyctènes</strong>, de <strong>décollements bulleux</strong> ou de <strong>purpura localisé</strong> ne sont PAS des signes de gravité en soi, car ils peuvent être présents dans un érysipèle non compliqué.</p>"},{"i":"e8220d61b934","n":155,"o":"155-17","u":"Contenu multimédia","t":"Dermohypodermite bactérienne non nécrosante (photographies d'un érysipéle adulte, d'une dermohypodermite non nécrosante enfant)","q":"Quels sont les signes sémiologiques classiques d'un érysipèle (dermohypodermite bactérienne non nécrosante) chez l'adulte ?","a":"<p>L'érysipèle de l'adulte se caractérise par :</p><ul><li>Un <strong>placard inflammatoire</strong> unilatéral, souvent au membre inférieur.</li><li>Il est <strong>rouge, chaud, œdémateux, douloureux</strong>.</li><li>La <strong>limite est nette</strong>, parfois avec un <strong>bourrelet périphérique</strong> (notamment au visage).</li><li>On peut observer un <strong>décollement bulleux</strong> superficiel ou un <strong>purpura localisé</strong>.</li></ul>"},{"i":"ee936168eb34","n":155,"o":"155-17","u":"Contenu multimédia","t":"Dermohypodermite bactérienne non nécrosante (photographies d'un érysipéle adulte, d'une dermohypodermite non nécrosante enfant)","q":"Quelle est la particularité sémiologique de la dermohypodermite bactérienne non nécrosante (DHBNN) chez l'enfant ?","a":"<p>Chez l'enfant, la DHBNN se présente également comme un <strong>placard érythémateux</strong>, souvent une complication survenant au décours d'une <strong>varicelle</strong>. Il est important de rechercher systématiquement la <strong>porte d'entrée</strong> et une <strong>adénopathie satellite</strong> associée.</p>"},{"i":"0502434bf13a","n":155,"o":"155-18","u":"Examens complémentaires","t":"Dermohypodermite bactérienne non nécrosante : connaître les examens à réaliser (et à ne pas réaliser)","q":"Dans quels contextes spécifiques des prélèvements microbiologiques sont-ils indiqués face à une dermohypodermite bactérienne non nécrosante (érysipèle) ?","a":"<p>Des prélèvements microbiologiques (porte d'entrée, hémocultures) sont indiqués uniquement dans les situations suivantes :</p><ul><li><strong>Morsure animale/humaine</strong></li><li>Contexte <strong>post-traumatique</strong></li><li><strong>Voyage</strong> ou survenue en <strong>milieu aquatique</strong></li><li>Patient <strong>immunodéprimé</strong></li><li><strong>Infection nosocomiale</strong></li><li>Signes de <strong>gravité locaux ou généraux</strong></li></ul>"},{"i":"b7c3f2353de4","n":155,"o":"155-18","u":"Examens complémentaires","t":"Dermohypodermite bactérienne non nécrosante : connaître les examens à réaliser (et à ne pas réaliser)","q":"En cas de réalisation d'examens biologiques devant un érysipèle, quels résultats sont attendus ?","a":"<p>En cas de réalisation d'examens biologiques (NFS, CRP), on peut observer un <strong>syndrome inflammatoire</strong> avec <strong>hyperleucocytose à PNN</strong>.</p>"},{"i":"dbde6fd3e626","n":155,"o":"155-18","u":"Examens complémentaires","t":"Dermohypodermite bactérienne non nécrosante : connaître les examens à réaliser (et à ne pas réaliser)","q":"Quels examens complémentaires sont nécessaires devant un érysipèle typique non compliqué ?","a":"<p>Devant un érysipèle typique non compliqué, <strong>aucun examen complémentaire n'est nécessaire</strong>.</p>"},{"i":"e798a485759b","n":155,"o":"155-18","u":"Examens complémentaires","t":"Dermohypodermite bactérienne non nécrosante : connaître les examens à réaliser (et à ne pas réaliser)","q":"Quel est le rendement des hémocultures dans un érysipèle typique ?","a":"<p>Les hémocultures sont positives dans <strong>moins de 5 %</strong> des cas d'érysipèle, en raison d'une prolifération bactérienne paradoxalement faible.</p>"},{"i":"02a184b25469","n":155,"o":"155-19","u":"Prise en charge","t":"Connaître le principe du traitement d'une dermohypodermite bactérienne et la notion d'urgence médicochirurgicale dans les formes nécrosantes ; Dermohypodermite bactérienne non nécrosante : connaître le traitement (antibiothérapie recommandée et si allergie pénicilline, mesures complémentaires (adulte et enfant)","q":"Quelle est l'antibiothérapie de première intention pour une dermohypodermite bactérienne non nécrosante (érysipèle) chez l'adulte, et quelle est sa durée ?","a":"<p>L'antibiothérapie de première intention est l'<strong>Amoxicilline</strong>, administrée pendant <strong>7 jours</strong>. Elle peut être per os (PO) en ambulatoire ou intraveineuse (IV) si hospitalisation, puis relais PO.</p>"},{"i":"0f56f3c6f940","n":155,"o":"155-19","u":"Prise en charge","t":"Connaître le principe du traitement d'une dermohypodermite bactérienne et la notion d'urgence médicochirurgicale dans les formes nécrosantes ; Dermohypodermite bactérienne non nécrosante : connaître le traitement (antibiothérapie recommandée et si allergie pénicilline, mesures complémentaires (adulte et enfant)","q":"Quels sont les principes du traitement chirurgical et de l'antibiothérapie dans la prise en charge d'une dermohypodermite bactérienne nécrosante ?","a":"<ul><li><strong>Chirurgie :</strong> essentielle et répétée, elle comprend la <strong>mise à plat et l'excision des tissus nécrosés</strong>, le débridement et des lavages itératifs. Une amputation peut être nécessaire, ainsi qu'une colostomie ou cystostomie de décharge pour les formes périnéales.</li><li><strong>Antibiothérapie :</strong> par voie intraveineuse à fortes doses pendant <strong>14 à 21 jours</strong>. La molécule dépend du site :</li><ul><li>Membre/cervico-faciale : <strong>amoxicilline-acide clavulanique + clindamycine</strong>.</li><li>Abdomino-périnéale : <strong>pipéracilline-tazobactam ou imipénème</strong>.</li><li>Gangrène de Fournier : <strong>pénicilline + métronidazole + aminoside</strong>.</li><li>Toxicomane IV : <strong>amoxicilline-acide clavulanique</strong>, avec adjonction de <strong>vancomycine</strong> si suspicion de SARM.</li></ul></ul>"},{"i":"8ff356bad54e","n":155,"o":"155-19","u":"Prise en charge","t":"Connaître le principe du traitement d'une dermohypodermite bactérienne et la notion d'urgence médicochirurgicale dans les formes nécrosantes ; Dermohypodermite bactérienne non nécrosante : connaître le traitement (antibiothérapie recommandée et si allergie pénicilline, mesures complémentaires (adulte et enfant)","q":"Quelles sont les principales mesures complémentaires de prise en charge d'une dermohypodermite bactérienne non nécrosante chez l'adulte et l'enfant ?","a":"<ul><li>Prévention <strong>antitétanique</strong>.</li><li>Antalgiques (notamment <strong>paracétamol</strong>).</li><li><strong>Repos</strong> avec surélévation du membre atteint.</li><li>Contention veineuse après amélioration clinique.</li><li><strong>Anticoagulation préventive</strong> si facteurs de risque de thrombose.</li><li><strong>Attention :</strong> il ne faut <span style=\"text-decoration:underline;\">jamais</span> utiliser d'antibiothérapie locale, d'AINS ou de corticoïdes.</li></ul>"},{"i":"938e82cb6424","n":155,"o":"155-19","u":"Prise en charge","t":"Connaître le principe du traitement d'une dermohypodermite bactérienne et la notion d'urgence médicochirurgicale dans les formes nécrosantes ; Dermohypodermite bactérienne non nécrosante : connaître le traitement (antibiothérapie recommandée et si allergie pénicilline, mesures complémentaires (adulte et enfant)","q":"Pourquoi une dermohypodermite bactérienne ou fasciite nécrosante est-elle considérée comme une urgence médico-chirurgicale ?","a":"<p>Elle est considérée comme une <strong>urgence vitale médico-chirurgicale</strong> en raison d'une mortalité d'environ <strong>30 %</strong>, son pronostic étant directement lié à la <strong>précocité de la chirurgie</strong>. Elle nécessite une admission en soins intensifs.</p>"},{"i":"ff8e2ad8af19","n":155,"o":"155-19","u":"Prise en charge","t":"Connaître le principe du traitement d'une dermohypodermite bactérienne et la notion d'urgence médicochirurgicale dans les formes nécrosantes ; Dermohypodermite bactérienne non nécrosante : connaître le traitement (antibiothérapie recommandée et si allergie pénicilline, mesures complémentaires (adulte et enfant)","q":"Quelle est l'antibiothérapie recommandée en cas d'allergie à la pénicilline pour une dermohypodermite bactérienne non nécrosante (érysipèle) ?","a":"<p>En cas d'allergie à la pénicilline, la <strong>Pristinamycine</strong> ou la <strong>Clindamycine</strong> sont recommandées.</p>"},{"i":"1039e635564f","n":155,"o":"155-2","u":"Diagnostic positif","t":"Connaître les signes d'une infection candidosique et des mycoses (candidoses incluses) orale, génitale, unguéale, d'un pli","q":"Comment différencier une candidose d'une dermatophytose au niveau des grands plis ?","a":"<p>Pour les grands plis :</p><ul><li>La <strong>candidiose</strong> est généralement bilatérale et symétrique, avec un fond du pli érythémateux, un enduit blanchâtre, une fissure suintante et prurigineuse, et un bord émietté/pustuleux.</li><li>La <strong>dermatophytose</strong> est plutôt unilatérale au niveau inguinal, avec un fond de pli sec non érythémateux, et une bordure arrondie érythémato-squameuse à extension centrifuge.</li></ul>"},{"i":"357d97123990","n":155,"o":"155-2","u":"Diagnostic positif","t":"Connaître les signes d'une infection candidosique et des mycoses (candidoses incluses) orale, génitale, unguéale, d'un pli","q":"Comment se présentent les infections candiddosiques de la sphère orale ?","a":"<p>Les infections candidosiques orales peuvent être :</p><ul><li>Le <strong>muguet</strong> : érythème et enduit blanchâtre détachable au raclage.</li><li>La <strong>perlèche</strong> : intertrigo de la commissure labiale.</li><li>La <strong>glossite dépapillée</strong> en avant du V lingual.</li><li>Associées à une <strong>xérostomie</strong> et une <strong>dysgueusie</strong>.</li></ul>"},{"i":"44dcfcf80749","n":155,"o":"155-2","u":"Diagnostic positif","t":"Connaître les signes d'une infection candidosique et des mycoses (candidoses incluses) orale, génitale, unguéale, d'un pli","q":"Comment se manifeste une balanite ou balano-posthite candidosique chez l'homme ?","a":"<p>La balanite ou balano-posthite candidosique chez l'homme se présente généralement par un <strong>érythème du gland</strong>, des <strong>picotements après les rapports sexuels</strong>, et est souvent paucisymptomatique.</p>"},{"i":"9c0f7e566116","n":155,"o":"155-2","u":"Diagnostic positif","t":"Connaître les signes d'une infection candidosique et des mycoses (candidoses incluses) orale, génitale, unguéale, d'un pli","q":"Quelles sont les caractéristiques cliniques d'un onyxis candidosique par rapport à un onyxis dermatophytique ?","a":"<p>Un onyxis candidosique se manifeste par un <strong>périonyxis douloureux</strong> d'emblée, touchant plutôt les <strong>mains</strong>, évoluant vers un onyxis proximal marron-verdâtre. L'onyxis dermatophytique se caractérise par l'absence de périonyxis, touche plus fréquemment les <strong>orteils</strong>, débutant distalement par une leuconychie, puis une hyperkératose sous-unguéale et une onycholyse distale.</p>"},{"i":"fe48cc88c335","n":155,"o":"155-2","u":"Diagnostic positif","t":"Connaître les signes d'une infection candidosique et des mycoses (candidoses incluses) orale, génitale, unguéale, d'un pli","q":"Quels sont les signes cliniques d'une vulvovaginite candidosique ?","a":"<p>La vulvovaginite candidosique se manifeste par :</p><ul><li>Un <strong>prurit intense</strong>.</li><li>Des <strong>leucorrhées blanc-jaunâtre « lait caillé » grumeleuses</strong>.</li><li>Un <strong>érythème</strong> ou un <strong>œdème vulvaire</strong>.</li><li>Une éventuelle <strong>dyspareunie</strong>.</li></ul>"},{"i":"0a3fba776bda","n":155,"o":"155-20","u":"Prise en charge","t":"Savoir qu'il faut rechercher une porte d'entrée devant une dermohypodermite","q":"Quelles mesures de prévention des récidives de dermo-hypodermite bactérienne (DHB) peuvent être mises en place, en lien avec les portes d'entrée ?","a":"<ul><li><strong>Sécher systématiquement entre les orteils</strong>.</li><li><strong>Traiter les intertrigos</strong>.</li><li><strong>Désinfecter les plaies</strong> et les surveiller attentivement.</li><li><strong>Surveiller le pied diabétique</strong>.</li></ul>"},{"i":"43a9535c9e58","n":155,"o":"155-20","u":"Prise en charge","t":"Savoir qu'il faut rechercher une porte d'entrée devant une dermohypodermite","q":"Quelle est l'importance de la recherche d'une porte d'entrée devant une dermo-hypodermite bactérienne (DHB) ?","a":"<p>Devant toute DHB, la recherche systématique et le traitement de la porte d'entrée sont essentiels. C'est la <strong>clé de la prévention des récidives</strong> de DHB.</p>"},{"i":"4c664a1d6e71","n":155,"o":"155-20","u":"Prise en charge","t":"Savoir qu'il faut rechercher une porte d'entrée devant une dermohypodermite","q":"Quelles sont les principales portes d'entrée à rechercher devant une dermo-hypodermite bactérienne (DHB) ?","a":"<ul><li>L'<strong>intertrigo interorteils</strong>, le plus souvent d'origine <strong>dermatophytique</strong>, est la principale porte d'entrée de l'érysipèle de jambe.</li><li>Les <strong>plaies ou érosions traumatiques</strong>.</li><li>L'<strong>ulcère de jambe</strong>.</li></ul>"},{"i":"624c05c6f57e","n":155,"o":"155-21","u":"Physiopathologie","t":"Connaître la définition et physiopathologie de l'anthrax et du furoncle","q":"Quelle est la définition et les caractéristiques physiopathologiques de la folliculite ?","a":"<p>La folliculite est une infection <strong>superficielle de l'ostium folliculaire</strong>, le plus souvent due à <em><strong>Staphylococcus aureus</strong></em>. Elle est favorisée par la macération et les frottements.</p>"},{"i":"70a00947dab8","n":155,"o":"155-21","u":"Physiopathologie","t":"Connaître la définition et physiopathologie de l'anthrax et du furoncle","q":"Quelle est la cause bactérienne majoritaire des infections du follicule pilo-sébacé comme le furoncle et l'anthrax ?","a":"<p>La cause bactérienne majoritaire est <em><strong>Staphylococcus aureus</strong></em>.</p>"},{"i":"d44010535fcb","n":155,"o":"155-21","u":"Physiopathologie","t":"Connaître la définition et physiopathologie de l'anthrax et du furoncle","q":"Quelle est la définition et les caractéristiques physiopathologiques du furoncle ?","a":"<p>Le furoncle est une infection <strong>profonde et nécrosante</strong> de l'<strong>ensemble du follicule pilo-sébacé</strong>, entraînant la disparition du poil dans la nécrose. Il est majoritairement dû à <em><strong>Staphylococcus aureus</strong></em> et favorisé par la macération et les frottements. Un furoncle mature forme un <strong>bourbillon</strong> (cône de nécrose central) en <strong>5 à 10 jours</strong>.</p>"},{"i":"d5b666a5c3c7","n":155,"o":"155-21","u":"Physiopathologie","t":"Connaître la définition et physiopathologie de l'anthrax et du furoncle","q":"Qu'est-ce que la furonculose et quel peut en être le mécanisme sous-jacent ?","a":"<p>La furonculose correspond à la <strong>répétition chronique de furoncles</strong>. Elle peut être liée à un <strong>portage nasal de <em>Staphylococcus aureus</em></strong>, notamment les souches productrices de la <strong>leucocidine de Panton-Valentine</strong>.</p>"},{"i":"f3e5e043691a","n":155,"o":"155-21","u":"Physiopathologie","t":"Connaître la définition et physiopathologie de l'anthrax et du furoncle","q":"Quelle est la définition de l'anthrax en dermatologie ?","a":"<p>L'anthrax est un <strong>conglomérat de plusieurs furoncles</strong>, résultant d'une infection multiple et étendue des follicules pilo-sébacés.</p>"},{"i":"483ba618f4ff","n":155,"o":"155-22","u":"Diagnostic positif","t":"Connaître les signes cliniques du furoncle","q":"Quelle est la caractéristique sémiologique initiale du furoncle sur une zone pileuse ?","a":"<p>Il se manifeste initialement comme une <strong>papule</strong> ou un <strong>nodule inflammatoire</strong>, douloureux, centré par une petite <strong>pustule</strong>.</p>"},{"i":"5780176d7c86","n":155,"o":"155-22","u":"Diagnostic positif","t":"Connaître les signes cliniques du furoncle","q":"Quelle est l'issue habituelle de la guérison d'un furoncle ?","a":"<p>La guérison d'un furoncle laisse une <strong>cicatrice séquellaire</strong>.</p>"},{"i":"9692cdccba7a","n":155,"o":"155-22","u":"Diagnostic positif","t":"Connaître les signes cliniques du furoncle","q":"Comment évolue un furoncle après les premiers signes cliniques ?","a":"<p>Il évolue en <strong>5 à 10 jours</strong>, avec la maturation d'une zone nécrotique centrale appelée <strong>bourbillon</strong>. À noter une <strong>apyrexie</strong> généralement, sauf en cas de forme profuse ou compliquée.</p>"},{"i":"5e390316e467","n":155,"o":"155-23","u":"Contenu multimédia","t":"Photographie de furoncle","q":"Comment reconnaître une lésion de furoncle à l'examen clinique ?","a":"<p>Une lésion de furoncle se présente comme un <strong>nodule érythémateux</strong>, centré par une <strong>pustule</strong>, situé sur une <strong>zone pileuse</strong>. À maturation, on observe un <strong>bourbillon</strong>, qui est un cône de nécrose central.</p>"},{"i":"734c4af7d20b","n":155,"o":"155-23","u":"Contenu multimédia","t":"Photographie de furoncle","q":"Quel est le germe principalement responsable des furoncles et quels sont les risques évolutifs ?","a":"<p>Le germe responsable est le plus souvent <em><strong>Staphylococcus aureus</strong></em>. Un furoncle mature en <strong>5 à 10 jours</strong> et laisse une <strong>cicatrice</strong>. Un <strong>furoncle centro-facial manipulé</strong> expose au risque de <strong>staphylococcie maligne de la face</strong>.</p>"},{"i":"ff9fb80320c6","n":155,"o":"155-23","u":"Contenu multimédia","t":"Photographie de furoncle","q":"Quelle est la définition clinique d'un furoncle ?","a":"<p>Un furoncle est un <strong>nodule inflammatoire douloureux</strong> centré par une pustule, évoluant vers la formation d'un <strong>bourbillon nécrotique</strong>.</p>"},{"i":"010b6638c865","n":155,"o":"155-27","u":"Définition","t":"Connaître la définition, la physiopathologie, l'épidémiologie de l'impétigo et de l'impétiginisation","q":"Qu'est-ce que l'impétiginisation et dans quel contexte survient-elle le plus souvent ?","a":"<p>L'impétiginisation est une <strong>infection bactérienne surajoutée à une dermatose prurigineuse préexistante</strong>. C'est la forme principale d'impétigo chez l'<strong>adulte</strong>, chez qui l'impétigo est rarement primitif.</p>"},{"i":"0e0b14667951","n":155,"o":"155-27","u":"Définition","t":"Connaître la définition, la physiopathologie, l'épidémiologie de l'impétigo et de l'impétiginisation","q":"Quel est l'agent causal spécifique de l'impétigo bulleux et son mécanisme physiopathologique ?","a":"<p>L'impétigo bulleux est causé par <strong><em>Staphylococcus aureus</em></strong> (staphylocoque doré) producteur d'<strong>exfoliatines A et B</strong>. Ces toxines ciblent la <strong>desmogléine 1</strong>, entraînant une fragilisation de la jonction entre les kératinocytes et la formation de bulles.</p>"},{"i":"7ea11800cc8f","n":155,"o":"155-27","u":"Définition","t":"Connaître la définition, la physiopathologie, l'épidémiologie de l'impétigo et de l'impétiginisation","q":"Quels sont les principaux germes responsables de l'impétigo et leur répartition en France ?","a":"<ul><li><strong><em>Staphylococcus aureus</em></strong> (staphylocoque doré) est retrouvé dans <strong>70 à 90 %</strong> des cas.</li><li>Le <strong>streptocoque</strong> est retrouvé dans environ <strong>30 %</strong> des cas.</li><li>Une association des deux germes est possible.</li></ul>"},{"i":"8e6e1b81235f","n":155,"o":"155-27","u":"Définition","t":"Connaître la définition, la physiopathologie, l'épidémiologie de l'impétigo et de l'impétiginisation","q":"Cite des exemples de dermatoses sous-jacentes pouvant s'impétiginiser.","a":"<ul><li><strong>Eczéma</strong></li><li><strong>Varicelle</strong></li><li><strong>Lymphome cutané</strong></li><li>Lésions de grattage diverses (ex: <strong>gale</strong>, <strong>pédiculose</strong>)</li></ul>"},{"i":"e13fb0088cbc","n":155,"o":"155-27","u":"Définition","t":"Connaître la définition, la physiopathologie, l'épidémiologie de l'impétigo et de l'impétiginisation","q":"Quelles sont les caractéristiques épidémiologiques de l'impétigo ?","a":"<ul><li>C'est l'infection bactérienne cutanée la plus fréquente chez l'<strong>enfant</strong>.</li><li>Elle est favorisée par un <strong>milieu défavorisé</strong>.</li><li>Elle est <strong>très contagieuse</strong>, principalement par <strong>manuportage</strong>, pouvant entraîner des <strong>épidémies intrafamiliales ou scolaires</strong>.</li></ul>"},{"i":"fc87a7a14f86","n":155,"o":"155-27","u":"Définition","t":"Connaître la définition, la physiopathologie, l'épidémiologie de l'impétigo et de l'impétiginisation","q":"Quelle est la définition de l'impétigo ?","a":"<p>L'impétigo est une infection bactérienne de la <strong>couche cornée</strong> de l'épiderme, non immunisante, expliquant les possibles récidives.</p>"},{"i":"3d708ed517d9","n":155,"o":"155-28","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'un impétigo crouteux, d'un impétigo bulleux, d'une impétiginisation","q":"Dans quels cas un prélèvement bactériologique est-il indiqué pour l'impétigo ?","a":"<p>Un <strong>prélèvement bactériologique</strong> (à réaliser sur une <strong>vésicule ou une bulle non rompue</strong>) est réservé aux cas :</p><ul><li><strong>compliqués</strong>,</li><li><strong>résistants</strong> aux traitements habituels,</li><li><strong>atypiques</strong>,</li><li>ou dans le cadre d'<strong>études épidémiologiques</strong>.</li></ul>"},{"i":"56436bf3959d","n":155,"o":"155-28","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'un impétigo crouteux, d'un impétigo bulleux, d'une impétiginisation","q":"Quelles sont les caractéristiques cliniques générales d'un impétigo, quelle que soit sa forme ?","a":"<ul><li>L'<strong>état général</strong> du patient est généralement <strong>conservé</strong>.</li><li>Le patient est <strong>apyrexique</strong> (pas de fièvre).</li><li>On peut retrouver une <strong>adénopathie satellite</strong>.</li></ul>"},{"i":"d12e9175aebb","n":155,"o":"155-28","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'un impétigo crouteux, d'un impétigo bulleux, d'une impétiginisation","q":"Quelles sont les particularités cliniques de l'impétigo bulleux ?","a":"<p>L'impétigo bulleux se caractérise par :</p><ul><li>La présence de <strong>bulles</strong>, causées par des <strong>exfoliatines</strong> agissant sur la <strong>desmogléine 1</strong>.</li><li>Il touche particulièrement le <strong>nouveau-né</strong> et le <strong>nourrisson</strong>.</li><li>Les localisations sont souvent <strong>péri-anales</strong> ou <strong>génitales</strong>, parfois appelé « pemphigus des crèches » en raison de son aspect.</p></li></ul>"},{"i":"d48aad127749","n":155,"o":"155-28","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'un impétigo crouteux, d'un impétigo bulleux, d'une impétiginisation","q":"Qu'est-ce que l'impétiginisation ?","a":"<p>L'impétiginisation correspond à l'apparition de <strong>croûtes mélicériques</strong> sur une <strong>dermatose prurigineuse préexistante</strong>.</p>"},{"i":"f92cec8049e1","n":155,"o":"155-28","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'un impétigo crouteux, d'un impétigo bulleux, d'une impétiginisation","q":"Quelles sont les lésions dermatologiques typiques de l'impétigo croûteux ?","a":"<p>L'impétigo croûteux se caractérise par :</p><ul><li>Des <strong>vésico-bulles fragiles</strong> qui évoluent en <strong>pustules</strong> puis se rompent pour former des <strong>croûtes mélicériques jaunâtres</strong> (décrites comme du « miel cristallisé »).</li><li>Les lésions forment des <strong>placards polycycliques</strong>, préférentiellement <strong>péri-orificiels</strong>.</li><li>La guérison se fait <strong>sans laisser de cicatrice</strong>.</li></ul>"},{"i":"fbd5d55e2574","n":155,"o":"155-28","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'un impétigo crouteux, d'un impétigo bulleux, d'une impétiginisation","q":"Comment se réalise le diagnostic d'un impétigo croûteux, bulleux ou d'une impétiginisation ?","a":"<p>Le diagnostic de l'impétigo croûteux, bulleux ou de l'impétiginisation est classiquement un diagnostic <strong>clinique</strong>.</p>"},{"i":"31e862dd603f","n":155,"o":"155-29","u":"Contenu multimédia","t":"Impétigo : photographies d'un impétigo crouteux, d'un impétigo bulleux, d'une impétiginisation)","q":"Quelle est la présentation clinique caractéristique de l'ecthyma et quel est son agent causal le plus fréquent ?","a":"<p>L'ecthyma, également appelé impétigo creusant, se caractérise par la présence d'une <strong>croûte noirâtre</strong> associée à une <strong>ulcération</strong> sous-jacente. Il s'agit d'une forme plus profonde d'impétigo, le plus souvent due au <strong>streptocoque du groupe A</strong>.</p>"},{"i":"419b11414cd1","n":155,"o":"155-29","u":"Contenu multimédia","t":"Impétigo : photographies d'un impétigo crouteux, d'un impétigo bulleux, d'une impétiginisation)","q":"Quelle est la présentation typique de l'impétigo croûteux à l'examen clinique ?","a":"<p>L'impétigo croûteux se caractérise par des <strong>croûtes mélicériques jaunâtres</strong>, souvent comparées à du « miel cristallisé », sur des lésions en <strong>placards polycycliques</strong> à contours circinés, fréquemment péri-orificielles.</p>"},{"i":"d0e77cf3bef8","n":155,"o":"155-29","u":"Contenu multimédia","t":"Impétigo : photographies d'un impétigo crouteux, d'un impétigo bulleux, d'une impétiginisation)","q":"Qu'est-ce que l'impétiginisation et comment la reconnaître cliniquement ?","a":"<p>L'impétiginisation est la surinfection bactérienne d'une dermatose préexistante, généralement <strong>prurigineuse</strong>. Elle se manifeste par l'apparition de <strong>croûtes</strong> typiques de l'impétigo sur les lésions de la dermatose initiale.</p>"},{"i":"dd36b8f111c9","n":155,"o":"155-29","u":"Contenu multimédia","t":"Impétigo : photographies d'un impétigo crouteux, d'un impétigo bulleux, d'une impétiginisation)","q":"Comment l'impétigo bulleux se distingue-t-il visuellement de l'impétigo croûteux ?","a":"<p>L'impétigo bulleux se caractérise par des <strong>bulles fragiles sous-cornées</strong>, provoquées par les exotoxines exfoliatines bactériennes. Contrairement à l'impétigo croûteux, les bulles sont le signe clinique prédominant avant l'éventuelle rupture et formation de croûtes.</p>"},{"i":"0837b5513642","n":155,"o":"155-3","u":"Physiopathologie","t":"Connaître les facteurs favorisants des infections cutanéo muqueuses à candida et mycoses","q":"Quels sont les facteurs favorisant les infections cutanéo-muqueuses à Malassezia (pityriasis versicolor) ?","a":"<ul><li><strong>Peau grasse</strong></li><li><strong>Sudation</strong></li><li><strong>Chaleur</strong> et <strong>humidité</strong></li><li>Périodes estivales ou <strong>voyages tropicaux</strong></li></ul>"},{"i":"3d1b18c1ec2a","n":155,"o":"155-3","u":"Physiopathologie","t":"Connaître les facteurs favorisants des infections cutanéo muqueuses à candida et mycoses","q":"Dans quel contexte Candida albicans passe-t-il d'un état saprophyte à l'état parasitaire ?","a":"<p>Candida albicans passe à l'état parasitaire exclusivement sous l'influence de <strong>facteurs favorisants</strong>, notamment un <strong>déséquilibre de la flore muqueuse</strong>.</p>"},{"i":"4382af369c4e","n":155,"o":"155-3","u":"Physiopathologie","t":"Connaître les facteurs favorisants des infections cutanéo muqueuses à candida et mycoses","q":"Quels sont les facteurs locaux favorisant les infections cutanéo-muqueuses à Candida ?","a":"<ul><li><strong>Chaleur</strong>, <strong>humidité</strong>, <strong>macération</strong></li><li><strong>pH acide</strong>, milieu riche en <strong>sucre</strong></li><li><strong>Obésité</strong>, <strong>prothèses dentaires</strong>, <strong>xérostomie</strong>, <strong>mucite post-radique</strong></li><li>Contact répété avec l'<strong>eau</strong> (plongeurs) ou le <strong>sucre</strong> (pâtissiers)</li></ul>"},{"i":"4479a70dd478","n":155,"o":"155-3","u":"Physiopathologie","t":"Connaître les facteurs favorisants des infections cutanéo muqueuses à candida et mycoses","q":"Quels sont les facteurs généraux favorisant les infections cutanéo-muqueuses à Candida ?","a":"<ul><li><strong>Immunodépression</strong> (VIH, corticoïdes, cancer, dénutrition)</li><li><strong>Diabète</strong></li><li><strong>Âges extrêmes</strong> (nourrissons, personnes âgées)</li><li><strong>Grossesse</strong></li><li><strong>Antibiothérapie systémique</strong></li><li><strong>Oestroprogestatifs</strong></li></ul>"},{"i":"575ea80fdd2e","n":155,"o":"155-3","u":"Physiopathologie","t":"Connaître les facteurs favorisants des infections cutanéo muqueuses à candida et mycoses","q":"Quels sont les facteurs favorisant les infections à Dermatophytes ?","a":"<ul><li><strong>Milieu sportif</strong> (douches collectives, tatamis)</li><li><strong>Macération</strong></li><li><strong>Altération épidermique</strong> (microtraumatisme)</li><li><strong>Contact animal</strong> (chien, chat)</li><li><strong>Corticoïdes locaux</strong> (notamment pour les teignes)</li></ul>"},{"i":"0f38c13c52ef","n":155,"o":"155-4","u":"Contenu multimédia","t":"Photographies d'un exemple typique de ces mycoses","q":"Comment reconnaît-on un intertrigo candidosique typique sur le plan clinique ?","a":"<p>Un intertrigo candidosique se caractérise par :</p><ul><li>Un <strong>fond du pli érythémateux suintant</strong>.</li><li>Un <strong>enduit blanchâtre</strong>.</li><li>Des <strong>fissures</strong>.</li><li>Une présentation <strong>bilatérale et symétrique</strong>.</li></ul>"},{"i":"67e95ed72c81","n":155,"o":"155-4","u":"Contenu multimédia","t":"Photographies d'un exemple typique de ces mycoses","q":"Quels sont les signes caractéristiques d'une dermatophytie unguéale à T. rubrum sur le plan macroscopique ?","a":"<p>Une dermatophytie unguéale à <em>T. rubrum</em> se caractérise par une <strong>leuconychie</strong> et une <strong>onycholyse distale</strong>.</p>"},{"i":"c1d4f8a1a883","n":155,"o":"155-4","u":"Contenu multimédia","t":"Photographies d'un exemple typique de ces mycoses","q":"Comment se présente typiquement une teigne tondante microsporique (à M. canis) sur photographie ?","a":"<p>Une teigne tondante microsporique (à <em>M. canis</em>) se présente comme une <strong>grande plaque alopécique unique</strong>, <strong>arrondie</strong>, <strong>squameuse</strong>, avec des <strong>cheveux cassés courts</strong>.</p>"},{"i":"c9f96248607e","n":155,"o":"155-4","u":"Contenu multimédia","t":"Photographies d'un exemple typique de ces mycoses","q":"Quels sont les signes cliniques distinctifs du pityriasis versicolor ?","a":"<p>Le pityriasis versicolor se manifeste par des <strong>macules chamois du tronc</strong>, devenant <strong>achromiques après exposition solaire</strong>, et sont généralement <strong>non prurigineuses</strong>.</p>"},{"i":"e9f45d78dab6","n":155,"o":"155-4","u":"Contenu multimédia","t":"Photographies d'un exemple typique de ces mycoses","q":"Comment décrire l'aspect typique du muguet buccal ?","a":"<p>Le muguet buccal se caractérise par un <strong>enduit blanchâtre</strong> qui est <strong>détachable</strong>, recouvrant une <strong>muqueuse buccale érythémateuse</strong>.</p>"},{"i":"fa34536eb423","n":155,"o":"155-4","u":"Contenu multimédia","t":"Photographies d'un exemple typique de ces mycoses","q":"Quelles sont les particularités cliniques d'une dermatophytie de la peau glabre (herpès circiné) ?","a":"<p>Une dermatophytie de la peau glabre (herpès circiné) se présente comme une <strong>plaque arrondie</strong> avec une <strong>bordure vésiculo-squameuse</strong> et une <strong>guérison centrale</strong>.</p>"},{"i":"863fd7b6066c","n":155,"o":"155-7","u":"Définition","t":"Connaître la définition d'un panaris","q":"Quelle est la définition d'un panaris et quel est son agent pathogène le plus fréquent ?","a":"<p>Un panaris est une <strong>infection aiguë du repli unguéal</strong> (péri-unguéale). L'agent pathogène le plus souvent en cause est le <strong><em>Staphylococcus aureus</em></strong>.</p>"},{"i":"9b9807edb2c7","n":155,"o":"155-7","u":"Définition","t":"Connaître la définition d'un panaris","q":"Quelle est l'évolution typique d'un panaris non traité et quel diagnostic différentiel ne doit pas être incisé ?","a":"<p>L'évolution typique d'un panaris non traité comprend un stade <strong>phlegmasique initial</strong>, puis la formation possible d'une <strong>collection purulente</strong>. Le principal diagnostic différentiel à ne pas inciser est le <strong>panaris herpétique</strong>, caractérisé par des vésicules groupées et souvent retrouvé chez les professionnels de santé.</p><p>Devant un panaris, il est également essentiel de rechercher une <strong>porte d'entrée</strong> (piqûre, manucure) ou un <strong>corps étranger</strong> et de vérifier le <strong>statut antitétanique</strong> du patient.</p>"},{"i":"f9d0b149975f","n":155,"o":"155-7","u":"Définition","t":"Connaître la définition d'un panaris","q":"Quels sont les signes cliniques élémentaires d'un panaris ?","a":"<p>Les signes cliniques élémentaires d'un panaris sont un <strong>repli unguéal érythémateux</strong>, <strong>œdémateux</strong> et <strong>douloureux</strong>.</p>"},{"i":"389b91e4142d","n":155,"o":"155-8","u":"Définition","t":"Connaître la définition d'un abcès","q":"Quelle est la définition d'un abcès cutané ?","a":"<p>Un abcès cutané est une <strong>collection de pus</strong>, témoignant d'une résolution physiologique imparfaite d'une infection locale.</p>"},{"i":"3b3f7d3c0d42","n":155,"o":"155-8","u":"Définition","t":"Connaître la définition d'un abcès","q":"Comment un abcès cutané évolue-t-il cliniquement ?","a":"<p>Un abcès cutané se présente initialement comme une <strong>plaque ou un nodule érythémateux</strong>, inflammatoire et très douloureux. Il évolue en quelques jours vers une <strong>collection</strong> de consistance molle, avec <strong>fluctuation</strong> à la palpation.</p>"},{"i":"9efa8708a9b4","n":155,"o":"155-8","u":"Définition","t":"Connaître la définition d'un abcès","q":"Quel est le germe principal responsable des abcès cutanés non compliqués ?","a":"<p>Le germe principal des abcès cutanés est <strong><em>Staphylococcus aureus</em></strong> (S. aureus).</p>"}]};